 'privacy.marketplace.desc': 'The Online Store / Marketplace is an optional feature. If you choose to publish a store, you sign in with Google, and we collect your email address and name. This information — together with your store details and your record of acceptance of our terms — is stored on our infrastructure provider, Cloudflare, to identify you as the store owner, bind the storefront to your account, and run account-level operations such as publishing, editing, or removing your store. You can request deletion of this data at any time by contacting us. If you never use the Online Store / Marketplace, none of this information is collected.',
