 'privacy.overview.title': '概述',
 'privacy.overview.desc': 'photoZseo（"我们"、"我们的"、"本应用"）致力于保护您的隐私。本政策说明我们如何处理您的数据。',
 'privacy.collection.title': '数据收集',
 'privacy.collection.desc': 'photoZseo完全在您的设备上处理所有图像。我们不会将您的照片上传、存储或传输到任何服务器。唯一的例外是下文所述的可选"在线商店/市场"功能——如果您选择使用它，部分账户信息将发送到我们的服务器。',
 'privacy.collection.photos': '照片和图像：在您的设备上本地处理。永远不会发送到我们的服务器。',
 'privacy.collection.account': '账户信息：核心应用不需要账户。如果您使用可选的"在线商店/市场"功能，您将通过 Google 登录，我们会收集您的电子邮件地址和姓名（见下文"在线商店和市场"部分）。否则不会收集任何电子邮件、用户名或个人信息。',
 'privacy.collection.purchase': '购买数据：订阅和购买信息由Apple（App Store）管理。我们无法访问您的付款详情。',
 'privacy.collection.diagnostic': '诊断数据：可能收集匿名崩溃日志和性能指标，以帮助我们修复错误并提高稳定性。无个人标识符，无广告 ID，无跟踪。',
 'privacy.thirdparty.title': '第三方服务',
