 'privacy.thirdparty.revenuecat': 'RevenueCat：管理订阅状态。请参阅其隐私政策：revenuecat.com/privacy。',
 'privacy.thirdparty.firebase': 'Firebase Crashlytics（Google）：收集匿名崩溃报告和性能诊断。无 IDFA，无广告跟踪。详见 firebase.google.com/support/privacy。',
 'privacy.thirdparty.shopify': 'Shopify（仅导出）：photoZseo 不会连接 Shopify 的服务器。应用会将您的商品列表导出为 CSV、XLSX 或 DOCX 文件，由您自行上传到 Shopify Admin。只有当您主动分享或上传导出文件时，数据才会离开您的设备。',
 'privacy.marketplace.title': '在线商店和市场',
 'privacy.marketplace.desc': '"在线商店/市场"是一项可选功能。如果您选择发布商店，您将通过 Google 登录，我们会收集您的电子邮件地址和姓名。这些信息连同您的商店详情以及您接受我们条款的记录，将存储在我们的基础设施提供商 Cloudflare 上，用于识别您为商店所有者、将店面绑定到您的账户，以及执行账户级操作（如发布、编辑或删除您的商店）。您可以随时联系我们请求删除这些数据。如果您从未使用"在线商店/市场"，则不会收集任何此类信息。',
 'privacy.storage.title': '数据存储',
 'privacy.storage.desc': '所有项目数据、图像和设置都存储在您设备上的加密沙盒存储中。您可以随时从应用的设置中删除所有数据。',
 'privacy.camera.title': '相机和照片库访问',
 'privacy.camera.desc': '本应用请求访问您的相机和照片库以拍摄和导入产品照片。这些权限是可选的，可以随时在设备设置中撤销。',
 'privacy.biometric.title': '生物识别认证',
