 'faq.q6': 'Aboneliği istediğim zaman iptal edebilir miyim?',
 'faq.a6': 'Evet. Abonelikler App Store üzerinden faturalandırılır ve Ayarlar → Apple ID → Abonelikler\'den istediğiniz zaman iptal edebilirsiniz. Mevcut dönem sonuna kadar Pro\'yu kullanmaya devam edersiniz.',
 'faq.q7': 'Fotoğraflarım nereye gidiyor? Bir yere yükleniyor mu?',
 'faq.a7': 'Hiçbir yere. photoZseo her fotoğrafı cihazda işler. Siz açıkça paylaşmadıkça, dışa aktarmadıkça veya göndermedikçe hiçbir görsel veya üst veri telefonunuzdan çıkmaz.',

