 'features.camera.title': 'Profesyonel Kamera Stüdyosu',
 'features.camera.desc': 'Dokunarak odaklama, ızgara, seviye göstergesi, yönlü çekim modu, seri çekim ve ses tuşu deklanşörü ile dahili kamera.',
 'features.archive.title': 'Proje Arşivi',
 'features.archive.desc': 'Tüm ürün fotoğraflarınızı Apple Dosyalar tarzı klasörlerde düzenleyin. Her ürün için bir proje — renkli klasörler, sürükle bırak, yeniden adlandır, çoğalt.',
 'features.resize.title': 'Otomatik Kırpma ve Sıkıştırma',
 'features.resize.desc': 'Otomatik kırpma, boyutlandırma ve platform özelliklerine göre sıkıştırma. Kalite modu veya hedef dosya boyutu modu. JPEG, PNG, WebP çıktısı.',
 'features.seo.title': 'SEO Dosya Adları ve Alt Metin',
 'features.seo.desc': 'Ürün adı ve yön etiketlerinden arama motorlarına uygun dosya adları ve alt metin otomatik oluşturun. Her dil için Unicode desteği.',
 'features.presets.title': 'Platform Önayarları',
 'features.presets.desc': 'Amazon, Etsy, Shopify, Trendyol, Instagram, TikTok için tek dokunuşla önayarlar. Boyut, format ve kalite — hepsi önceden yapılandırılmış.',
 'features.video.title': 'Ürün Videosu',
 'features.video.desc': 'Uygulama içinde doğrudan ürün videoları kaydedin. Proje boyutlarına göre otomatik kırpma ve boyutlandırma. Reels, TikTok ve ürün listeleri için mükemmel.',
 'features.bgremoval.title': 'Arka Plan Kaldırma',
