 'support.title': 'Destek',
 'support.intro': 'Yardım etmek için buradayız! photoZseo hakkında herhangi bir sorunuz, sorununuz veya geri bildiriminiz varsa lütfen bize ulaşın.',
 'support.contact.title': 'Bize Ulaşın',
 'support.contact.email': 'E-posta:',
 'support.contact.response': '48 saat içinde yanıt vermeyi hedefliyoruz.',
 'support.faq.title': 'Sıkça Sorulan Sorular',
 'support.faq.upgrade.q': 'Pro\'ya nasıl yükseltirim?',
 'support.faq.upgrade.a': 'Uygulamayı açın, Ayarlar\'a gidin ve "Pro\'ya Yükselt"e dokunun. Haftalık, aylık, 3 aylık veya yıllık planlar arasından seçim yapabilirsiniz.',
 'support.faq.restore.q': 'Satın alımımı nasıl geri yüklerim?',
 'support.faq.restore.a': 'Uygulamada Ayarlar\'a gidin ve "Satın Alımları Geri Yükle"ye dokunun. Orijinal satın alma için kullandığınız Apple ID ile giriş yaptığınızdan emin olun.',
 'support.faq.cancel.q': 'Aboneliğimi nasıl iptal ederim?',
 'support.faq.cancel.a': 'Cihazınızın Ayarlar > Apple ID > Abonelikler > photoZseo > Aboneliği İptal Et bölümünü açın. Pro özellikleriniz mevcut fatura döneminin sonuna kadar aktif kalacaktır.',
 'support.faq.privacy.q': 'Fotoğraflarım bir sunucuya yükleniyor mu?',
 'support.faq.privacy.a': 'Hayır. Tüm görsel işleme tamamen cihazınızda gerçekleşir. Fotoğraflarınız asla herhangi bir sunucuya gönderilmez.',
 'support.faq.platforms.q': 'Hangi platformlar destekleniyor?',
 'support.faq.platforms.a': 'photoZseo; Amazon, Etsy, Shopify, Trendyol, Instagram, TikTok ve özel web formatları için optimize edilmiş önayarları destekler.',
 'support.faq.bug.q': 'Bir hata buldum. Nasıl bildirebilirim?',
 'support.faq.bug.a': 'Lütfen support@photozseo.com adresine sorunun açıklaması ve cihaz modeliniz/işletim sistemi sürümünüz ile birlikte e-posta gönderin.',
 'delete.title': 'Verilerinizi Silin',
 'delete.intro': 'photoZseo hesap gerektirmez. Tüm veriler cihazınızda yerel olarak saklanır. Aşağıdaki yöntemleri kullanarak tüm uygulama verilerini silebilirsiniz.',
 'delete.app.title': 'Yöntem 1: Uygulama İçinden',
 'delete.app.s1': 'photoZseo\'yu açın',
