 'delete.app.note': 'Bu, uygulamadaki tüm projeleri, görselleri ve ayarları kalıcı olarak silecektir.',
 'delete.email.title': 'Yöntem 2: E-posta ile',
 'delete.email.desc': 'Uygulamaya erişemiyorsanız, support@photozseo.com adresine "Verilerimi Sil" konu satırıyla bir e-posta gönderin, size süreç boyunca rehberlik edeceğiz.',
