 'faq.q1': '¿Cuáles son los requisitos de tamaño de foto de producto de Amazon?',
 'faq.a1': 'Amazon requiere imágenes de producto entre 1000×1000 y 2000×2000 píxeles sobre fondo blanco puro. photoZseo aplica estas especificaciones con un solo toque — sin redimensionamiento manual.',
 'faq.q2': '¿Cuál es el mejor tamaño universal de foto de producto?',
 'faq.a2': '2000×2000 píxeles, cuadrado (1:1), fondo blanco cumple los requisitos de prácticamente todos los marketplaces — Amazon, Etsy, Shopify, eBay, Walmart y más.',
 'faq.q3': '¿Cuántas plataformas admite photoZseo?',
 'faq.a3': '46 plataformas incluyendo Amazon, Walmart, Etsy, Shopify, eBay, TikTok Shop, Instagram Shopping, Trendyol, Hepsiburada, Poshmark, Pinterest, Mercado Libre y AliExpress.',
 'faq.q4': '¿Funciona sin internet?',
 'faq.a4': 'Sí. Todo el redimensionado, compresión, renombrado SEO y eliminación de fondos se ejecuta 100% en tu dispositivo. Sin subidas, sin nube, sin cuenta.',
 'faq.q5': '¿Hay un plan gratuito?',
 'faq.a5': 'Sí. El plan gratuito incluye proyectos ilimitados y todas las funciones principales. Las exportaciones llevan una pequeña marca de agua photoZseo y etiqueta en el nombre; Pro elimina ambas.',
 'faq.q6': '¿Puedo cancelar la suscripción en cualquier momento?',
 'faq.a6': 'Sí. Las suscripciones se facturan a través de la App Store y puedes cancelarlas en cualquier momento desde Ajustes → ID de Apple → Suscripciones. Mantienes Pro hasta el final del período actual.',
 'faq.q7': '¿A dónde van mis fotos? ¿Se suben a algún sitio?',
