 'feature.seo-filenames.title': 'Nombres SEO y texto alternativo',
 'feature.seo-filenames.lead': 'Nombres de archivo optimizados para buscadores generados automáticamente como blue-leather-bag-front.webp — listos para Google Imágenes, Shopify, Amazon y todos los rastreadores de e-commerce.',
 'feature.seo-filenames.b1.title': 'Posiciona en Google Imágenes',
 'feature.seo-filenames.b1.desc': 'Separado por guiones, minúsculas, seguro para plataformas. El formato exacto que prefieren los buscadores.',
 'feature.seo-filenames.b2.title': 'Unicode para cualquier idioma',
 'feature.seo-filenames.b2.desc': 'Turco, árabe, japonés, hindi — cada carácter se normaliza y romaniza cuando importa.',
 'feature.seo-filenames.b3.title': 'Alt text en un toque',
