 'feature.seo-filenames.s2.desc': 'Frente, atrás, lado, detalle, arriba — tus nombres se mantienen organizados.',
 'feature.seo-filenames.s3.title': 'Exporta a cualquier lugar',
 'feature.seo-filenames.s3.desc': 'El nombre SEO viaja con tu archivo a AirDrop, Shopify, email, Archivos — donde lo envíes.',
 'feature.platform-presets.title': '46 presets de plataforma',
 'feature.platform-presets.lead': 'Amazon pide 2000×2000. Etsy quiere 3:4. TikTok Shop prefiere 1:1. photoZseo ya lo sabe — elige la plataforma y aplicamos la especificación.',
 'feature.platform-presets.b1.title': 'Siempre actualizado',
 'feature.platform-presets.b1.desc': 'Cada versión refresca las reglas de tamaño, formato y peso para cada marketplace. Se acabaron las guías desactualizadas.',
 'feature.platform-presets.b2.title': 'Un toque, cada plataforma',
 'feature.platform-presets.b2.desc': 'Redimensiona, comprime y formatea con las especificaciones exactas que publican Amazon, Etsy, Shopify, eBay y Walmart.',
 'feature.platform-presets.b3.title': 'Lote entre plataformas',
 'feature.platform-presets.b3.desc': 'Misma foto, múltiples exportaciones de plataforma en un pase — comprimido y listo para subir.',
 'feature.platform-presets.s1.title': 'Selecciona tu plataforma',
 'feature.platform-presets.s1.desc': 'Amazon, Etsy, Shopify, TikTok Shop, Instagram — 46 para elegir.',
 'feature.platform-presets.s2.title': 'photoZseo aplica la especificación',
 'feature.platform-presets.s2.desc': 'Tamaño, relación de aspecto, formato, compresión y nombre de archivo, todo correcto.',
 'feature.platform-presets.s3.title': 'Exporta y sube',
 'feature.platform-presets.s3.desc': 'Exporta a Shopify (CSV/XLSX/DOCX), AirDrop, Archivos, Mail o un zip — listo para subida masiva.',
 'home.bandlabel': 'Optimizado para 46 plataformas',
 'home.howitworks': 'Cómo funciona',
 'home.howitworks.sub': 'Tres pasos. Una app. Todas las plataformas.',
 'home.step.shoot': 'Fotografía',
 'home.step.shoot.desc': 'Abre la cámara. Guías de recorte, cuadrícula, indicador de nivel y etiquetas de dirección listos. Solo toca el obturador.',
 'home.step.optimize': 'Optimiza',
 'home.step.optimize.desc': 'photoZseo recorta, redimensiona, comprime, renombra con palabras clave SEO y genera texto alternativo automáticamente. Todo en segundo plano.',
 'home.step.sell': 'Vende',
 'home.step.sell.desc': 'Exporta como CSV/XLSX/DOCX, comparte por AirDrop o envía a Shopify. Tus fotos están listas — sube y empieza a vender.',
