 'delete.app.s5': 'Confirme la eliminación',
 'delete.app.note': 'Esto eliminará permanentemente todos los proyectos, imágenes y configuraciones de la aplicación.',
 'delete.email.title': 'Opción 2: Por Email',
 'delete.email.desc': 'Si no puede acceder a la aplicación, envíe un correo a support@photozseo.com con el asunto "Eliminar Mis Datos" y le guiaremos a través del proceso.',
 'delete.email.response': 'Responderemos dentro de las 48 horas.',
