 'b2b.f.incoterms.t': 'Incoterms 2020',
 'b2b.f.incoterms.d': 'EXW · FOB · CIF · DAP · DDP: elija uno, se imprime en cada cotización.',
 'b2b.f.hs.t': 'HS / GTİP / NCM',
