// Nav (new)
 'nav.features': 'Funktionen',
 'home.headline': 'Fotografieren. Optimieren.<br/><span class="hero-accent">Verkaufen.</span>',
 'home.herosub': 'Produktfotos für jede Plattform — mit einem Tipp.',
 'home.footnote': 'Kostenlos nutzbar. Kein Konto nötig. 100% auf dem Gerät.',
 'stats.platforms': 'Plattformen',
 'stats.languages': 'Sprachen',
 'stats.ondevice': 'Auf dem Gerät',
 'stats.speed': 'Pro Foto',

 // FAQ
 'faq.title': 'Häufig gestellte Fragen',
 'faq.sub': 'Alles, was Verkäufer vor dem Download fragen.',
 'faq.q1': 'Welche Größenanforderungen gelten für Amazon-Produktfotos?',
 'faq.a1': 'Amazon verlangt Produktbilder zwischen 1000×1000 und 2000×2000 Pixeln auf reinweißem Hintergrund. photoZseo wendet diese Vorgaben mit einem Tipp an — keine manuelle Größenänderung.',
 'faq.q2': 'Was ist die beste universelle Produktfotogröße?',
 'faq.a2': '2000×2000 Pixel, quadratisch (1:1), weißer Hintergrund erfüllt die Anforderungen praktisch jedes Marktplatzes — Amazon, Etsy, Shopify, eBay, Walmart und mehr.',
 'faq.q3': 'Wie viele Plattformen unterstützt photoZseo?',
 'faq.a3': '46 Plattformen, darunter Amazon, Walmart, Etsy, Shopify, eBay, TikTok Shop, Instagram Shopping, Trendyol, Hepsiburada, Poshmark, Pinterest, Mercado Libre und AliExpress.',
 'faq.q4': 'Funktioniert es ohne Internet?',
 'faq.a4': 'Ja. Größenänderung, Kompression, SEO-Umbenennung und Hintergrundentfernung laufen zu 100% auf Ihrem Gerät. Keine Uploads, keine Cloud, kein Konto.',
 'faq.q5': 'Gibt es einen kostenlosen Plan?',
 'faq.a5': 'Ja. Der kostenlose Plan enthält unbegrenzte Projekte und alle Kernfunktionen. Exporte tragen ein kleines photoZseo-Wasserzeichen und einen Dateinamen-Tag; Pro entfernt beides.',
 'faq.q6': 'Kann ich das Abo jederzeit kündigen?',
 'faq.a6': 'Ja. Abonnements werden über den App Store abgerechnet und können jederzeit unter Einstellungen → Apple ID → Abonnements gekündigt werden. Pro bleibt bis zum Ende der laufenden Periode aktiv.',
 'faq.q7': 'Wohin gelangen meine Fotos? Werden sie irgendwo hochgeladen?',
 'faq.a7': 'Nirgendwohin. photoZseo verarbeitet jedes Foto auf dem Gerät. Kein Bild und keine Metadaten verlassen Ihr Telefon, es sei denn, Sie teilen, exportieren oder senden sie selbst.',

 // Platform specs table
 'specs.title': 'Plattform-Spezifikationen auf einen Blick',
 'specs.sub': 'Jeder Marktplatz hat eigene Foto-Regeln. Wir halten sie für Sie ein.',
 'specs.col.platform': 'Plattform',
 'specs.col.size': 'Empfohlene Größe',
 'specs.col.format': 'Format',
 'specs.col.notes': 'Hinweise',
 'specs.notes.whitebg': 'Weißer Hintergrund',
 'specs.notes.max20': 'Bis zu 20 MB',
 'specs.notes.max12': 'Bis zu 12 MB',
 'specs.notes.max8': 'Bis zu 8 MB',
 'specs.notes.square': '1:1 Quadrat',
 'specs.notes.vertical': '2:3 vertikal',
 'specs.footnote': 'Spezifikationen für 2026 verifiziert. Automatisch aktualisiert mit jeder App-Version.',
 'specs.countLabel': 'Plattformen, alle automatisch konfiguriert',
