 'home.features.sub': 'Eine App ersetzt Ihren gesamten Foto-Workflow.',
 'home.privacy': '100% auf dem Gerät. Kein Cloud-Upload. Offline nutzbar. Ihre Fotos verlassen nie Ihr Telefon.',
