 'hero.title': 'photoZseo',
 'hero.tagline': 'Ihr All-in-One-Produktfoto-Studio. Aufnehmen, organisieren, optimieren und plattformfertige Bilder exportieren — alles auf Ihrem Gerät.',
 'hero.cta': 'Im App Store laden',
 'platforms.title': 'Für jeden Marktplatz entwickelt',
 'features.title': 'Funktionen',
 'features.camera.title': 'Profi-Kamera-Studio',
 'features.camera.desc': 'Integrierte Kamera mit Tippen-zum-Fokussieren, Rasterüberlagerung, Wasserwaage, Richtungsaufnahmemodus, Serienaufnahme und Lautstärketasten-Auslöser.',
 'features.archive.title': 'Projektarchiv',
 'features.archive.desc': 'Organisieren Sie alle Produktfotos in Apple-Dateien-artigen Ordnern. Ein Projekt pro Produkt — farbcodierte Ordner, Drag & Drop, Umbenennen, Duplizieren.',
 'features.resize.title': 'Automatisches Zuschneiden & Komprimieren',
 'features.resize.desc': 'Automatisches Zuschneiden, Größenänderung und Komprimierung auf exakte Plattform-Spezifikationen. Qualitätsmodus oder Zieldateigröße. JPEG-, PNG-, WebP-Ausgabe.',
 'features.seo.title': 'SEO-Dateinamen & Alt-Text',
 'features.seo.desc': 'Automatische Generierung suchoptimierter Dateinamen und Alt-Texte aus Produktname und Richtungs-Tags. Unicode-Unterstützung für jede Sprache.',
 'features.presets.title': 'Plattform-Voreinstellungen',
 'features.presets.desc': 'Ein-Tipp-Voreinstellungen für Amazon, Etsy, Shopify, Trendyol, Instagram, TikTok. Größe, Format und Qualität — alles vorkonfiguriert.',
 'features.video.title': 'Produktvideo',
 'features.video.desc': 'Nehmen Sie Produktvideos direkt in der App auf. Automatisches Zuschneiden und Anpassen an Ihre Projektmaße. Perfekt für Reels, TikTok und Angebote.',
 'features.bgremoval.title': 'Hintergrundentfernung',
 'features.bgremoval.desc': 'KI-gestützte Hintergrundentfernung mit einem Tippen. Ersetzen durch Weiß, Schwarz, benutzerdefinierte Farbe oder transparentes PNG für professionelle Angebote.',
 'features.logo.title': 'Logo- & Wasserzeichen-Overlay',
 'features.logo.desc': 'Fügen Sie Ihr Markenlogo zu jedem Export hinzu. Wählen Sie aus 9 Positionen, passen Sie Größe und Deckkraft an. Ihr Branding, automatisiert.',
 'features.batch.title': 'Batch-Export & Zip',
 'features.batch.desc': 'Exportieren Sie ganze Projekte oder Ordner als Zip-Dateien. Teilen via AirDrop, E-Mail oder Dateien-App — bereit zum Massen-Upload.',
 'features.ondevice.title': '100% auf dem Gerät & Privat',
 'features.ondevice.desc': 'Die gesamte Verarbeitung erfolgt auf Ihrem Gerät. Keine Uploads, keine Cloud, kein Konto erforderlich. Ihre Produktfotos bleiben Ihre.',
