 'multicap.title': 'Ein Verschluss. Mehrere Ausgänge.',
 'multicap.sub': 'Machen Sie ein Foto. Die App erstellt gleichzeitig separate, optimierte Projekte in verschiedenen Größen, Formaten und Qualitätseinstellungen. Kein Wiederexport, kein zweites Shooting.',
