 'rename.f.unicode.t': '🌐 Vollständiger Unicode',
 'rename.f.unicode.d': 'Türkisch (ş→s, ç→c, ğ→g), Chinesisch, Japanisch, Arabisch, Koreanisch, Kyrillisch – alle in URL-sichere Slugs transkribiert.',
 'rename.f.cascade.t': '⚡ Atomkaskade',
 'rename.f.cascade.d': 'Eine Umbenennung löst Slug + Alt + SEO + Meta + Produktbeschreibung + Ordner + jede Fotodatei aus – in einer einzigen Transaktion.',
 'rename.f.batch.t': '📦 Chargensicher',
 'rename.f.batch.d': 'Die Reihenfolge pro Richtung bleibt erhalten: Die Anzahl der Vorder-, Rückseiten und Seiten wird erneut auf das neue Stück angewendet. Keine Kollisionen.',
