 'faq.q1': 'Amazonの商品写真のサイズ要件は何ですか？',
 'faq.a1': 'Amazonは純白背景で1000×1000〜2000×2000ピクセルの商品画像を要求します。photoZseoはこれらの仕様をワンタップで適用します — 手動リサイズ不要。',
