 'privacy.overview.desc': 'photoZseo（「当社」「当アプリ」）はお客様のプライバシーの保護に取り組んでいます。このポリシーでは、お客様のデータの取り扱いについて説明します。',
 'privacy.collection.title': 'データ収集',
 'privacy.collection.desc': 'photoZseoはすべての画像をお客様のデバイス上で完全に処理します。写真をサーバーにアップロード、保存、送信することはありません。唯一の例外は、以下で説明する任意のオンラインストア／マーケットプレイス機能です。これを利用する場合、一部のアカウント情報が当社のサーバーに送信されます。',
 'privacy.collection.photos': '写真と画像：デバイス上でローカルに処理されます。当社のサーバーに送信されることはありません。',
 'privacy.collection.account': 'アカウント情報：コアアプリはアカウントを必要としません。任意のオンラインストア／マーケットプレイスを利用する場合は Google でサインインし、メールアドレスと氏名を収集します（下記の「オンラインストアとマーケットプレイス」セクションをご覧ください）。それ以外の場合、メールアドレス、ユーザー名、個人情報は一切収集しません。',
 'privacy.collection.purchase': '購入データ：サブスクリプションと購入情報はApple（App Store）が管理します。お客様の支払い情報にアクセスすることはありません。',
 'privacy.collection.diagnostic': '診断データ：バグ修正と安定性向上のために匿名のクラッシュログとパフォーマンス指標を収集する場合があります。個人識別子なし、広告 ID なし、トラッキングなし。',
 'privacy.thirdparty.title': 'サードパーティサービス',
 'privacy.thirdparty.apple': 'Apple App Store：購入とサブスクリプションを管理。',
 'privacy.thirdparty.revenuecat': 'RevenueCat：サブスクリプション状態を管理。プライバシーポリシーの詳細はrevenuecat.com/privacyをご覧ください。',
 'privacy.thirdparty.firebase': 'Firebase Crashlytics（Google）：匿名のクラッシュレポートとパフォーマンス診断を収集します。IDFA なし、広告トラッキングなし。詳細は firebase.google.com/support/privacy をご覧ください。',
 'privacy.thirdparty.shopify': 'Shopify（エクスポートのみ）：photoZseo は Shopify のサーバーには接続しません。アプリは商品リストを CSV、XLSX または DOCX ファイルとしてエクスポートします。そのファイルはユーザー自身が Shopify Admin にアップロードします。データは、ユーザーがエクスポートファイルを共有またはアップロードしたときにのみ端末から離れます。',
 'privacy.marketplace.title': 'オンラインストアとマーケットプレイス',
 'privacy.marketplace.desc': 'オンラインストア／マーケットプレイスは任意の機能です。ストアを公開する場合は Google でサインインし、メールアドレスと氏名を収集します。この情報は、ストアの詳細および当社の規約に同意した記録とともに、当社のインフラ提供業者である Cloudflare に保存され、お客様をストアの所有者として識別し、ストアフロントをアカウントに紐付け、ストアの公開・編集・削除などのアカウントレベルの操作を行うために使用されます。当社に連絡することで、いつでもこのデータの削除を請求できます。オンラインストア／マーケットプレイスを一切利用しない場合、これらの情報は収集されません。',
 'privacy.storage.title': 'データ保存',
 'privacy.storage.desc': 'すべてのプロジェクトデータ、画像、設定は暗号化されたサンドボックスストレージを使用してデバイス上にローカルに保存されます。アプリの設定からいつでもすべてのデータを削除できます。',
 'privacy.camera.title': 'カメラとフォトライブラリへのアクセス',
 'privacy.camera.desc': 'アプリは商品写真の撮影とインポートのためにカメラとフォトライブラリへのアクセスを要求します。これらの権限はオプションであり、デバイスの設定からいつでも取り消すことができます。',
 'privacy.biometric.title': '生体認証',
 'privacy.biometric.desc': 'photoZseoはFace ID、Touch ID、またはデバイスのパスコードを使用したオプションのアプリロック機能を提供します。生体認証データはデバイスのオペレーティングシステムによって完全に処理されます — photoZseoは生体認証データにアクセス、保存、送信することはありません。',
 'privacy.children.title': 'お子様のプライバシー',
 'privacy.children.desc': 'photoZseoは13歳未満のお子様を対象としていません。お子様から故意に個人情報を収集することはありません。',
 'privacy.changes.title': 'ポリシーの変更',
 'privacy.changes.desc': '当社はこのポリシーを随時更新することがあります。重要な変更については、アプリまたはこのページを通じてお知らせします。',
 'privacy.contact.title': 'お問い合わせ',
 'privacy.contact.desc': 'このプライバシーポリシーについてご質問がある場合は、こちらにお問い合わせください：',
 'terms.title': '利用規約',
 'terms.updated': '最終更新：',
 'terms.date': '2026年4月21日',
 'terms.acceptance.title': '規約の承諾',
 'terms.acceptance.desc': 'photoZseoをダウンロードまたは使用することにより、これらの利用規約に同意したものとみなされます。同意しない場合は、アプリを使用しないでください。',
 'terms.description.title': 'サービスの説明',
 'terms.description.desc': 'photoZseoは、ECセラーが商品写真をリサイズ、圧縮、SEOフレンドリーなファイル名の生成によって最適化するのを支援するモバイルアプリケーションです。すべての画像処理はデバイス上でローカルに実行されます。',
 'terms.subscriptions.title': 'サブスクリプションと支払い',
 'terms.subscriptions.f1': 'photoZseoはウォーターマーク付きエクスポートの無料版とフル機能のProサブスクリプションを提供しています。',
 'terms.subscriptions.f2': 'サブスクリプションはApple ID（App Store）アカウントを通じて請求されます。',
 'terms.subscriptions.f3': 'サブスクリプションは現在の期間終了の少なくとも24時間前にキャンセルされない限り、自動的に更新されます。',
 'terms.subscriptions.f4': 'デバイスの設定（Apple ID > サブスクリプション > サブスクリプション）でサブスクリプションを管理またはキャンセルできます。',
 'terms.subscriptions.f5': '返金はAppleがそれぞれの返金ポリシーに従って処理します。',
 'terms.plans.title': 'サブスクリプションプラン',
 'terms.plans.note': '価格はすべてUSDです。現地通貨での相当額はApp Storeが地域に基づいて設定します。',
 'terms.plans.starter': 'Starter — 月額 $9.99 または年額 $71.99',
