 'terms.plans.trial': '年額プランには7日間の無料トライアルが含まれます。',
 'terms.trial.title': '無料トライアル',
 'terms.trial.desc': '無料トライアルが提供されている場合、事前にキャンセルされない限り、トライアル期間の終了時に自動的に有料サブスクリプションに移行します。',
 'terms.ip.title': '知的財産',
 'terms.ip.desc': 'アプリ、そのデザイン、コード、ブランディングはphotoZseoの所有物です。アプリを使用して処理した写真の完全な所有権はお客様に帰属します。',
 'terms.use.title': '許容される使用',
 'terms.use.desc': '以下のことを行わないことに同意するものとします：',
 'terms.use.f1': 'アプリのリバースエンジニアリング、逆コンパイル、逆アセンブル。',
