 'terms.use.f3': 'アプリまたはその機能の再配布または再販売。',
 'terms.disclaimer.title': '免責事項',
 'terms.disclaimer.desc': 'photoZseoはいかなる保証もなく「現状のまま」提供されます。アプリの使用から生じるデータの損失または損害について責任を負いません。',
 'terms.liability.title': '責任の制限',
 'terms.liability.desc': '法律で許容される最大限の範囲で、photoZseoはアプリの使用から生じる間接的、付随的、または結果的な損害について責任を負いません。',
 'terms.changes.title': '規約の変更',
