 'archive.tagline': 'アーカイブはあなたとともに成長します。長年にわたる製品、顧客、見積もり — サーバーではなく携帯電話で検索できます。',
 'aisearch.title': 'AIによって発見されました。 ChatGPT、Perplexity、Google から引用。',
 'aisearch.sub': 'AI 検索エンジン (ChatGPT、Perplexity、Google AI Overovers、Claude) は、説明的なファイル名と構造化された代替テキストを備えた製品を引用しています。 photoZseo は、AI アシスタントが製品を見つけて推奨するために必要なものをすべての写真に提供します。',
 'aisearch.q.chatgpt': '「50ドル以下で良い手作りの革財布は何ですか？」',
 'aisearch.a.chatgpt.lead': 'YourShop で販売されている 49.99 ドルの手作りの青い革の財布は、カード スロットを備えており、高級だが手頃な価格という条件に一致します。',
 'aisearch.q.perplexity': '「2026年のベストブルーレザーウォレット — 情報源は？」',
 'aisearch.a.perplexity.lead': '最高評価のハンドメイド ブルー レザー ウォレット — プレミアム品質、5 つ星のレビュー。 YourShop の製品は、色、素材、角度を説明する明示的な代替テキストを持つ最もよく引用される例です。',
 'aisearch.q.google': '『革財布ハンドメイドプレミアム』',
 'aisearch.a.google.lead': 'ブルーレザーウォレット — 手作りのプレミアム。 49.99ドル。カードスロットとコインポケット。イスタンブールから発送します。',
