 // FAQ
 'faq.title': 'Perguntas frequentes',
 'faq.sub': 'Tudo o que vendedores perguntam antes de baixar.',
 'faq.q1': 'Quais são os requisitos de tamanho de foto de produto da Amazon?',
 'faq.a1': 'A Amazon exige imagens de produto entre 1000×1000 e 2000×2000 pixels em fundo branco puro. photoZseo aplica essas especificações com um único toque — sem redimensionamento manual.',
 'faq.q2': 'Qual é o melhor tamanho universal de foto de produto?',
 'faq.a2': '2000×2000 pixels, quadrado (1:1), fundo branco atende aos requisitos de praticamente todos os marketplaces — Amazon, Etsy, Shopify, eBay, Walmart e mais.',
 'faq.q3': 'Quantas plataformas o photoZseo suporta?',
 'faq.a3': '46 plataformas incluindo Amazon, Walmart, Etsy, Shopify, eBay, TikTok Shop, Instagram Shopping, Trendyol, Hepsiburada, Poshmark, Pinterest, Mercado Libre e AliExpress.',
 'faq.q4': 'Funciona sem internet?',
 'faq.a4': 'Sim. Redimensionamento, compressão, renomeação SEO e remoção de fundo rodam 100% no seu dispositivo. Sem uploads, sem nuvem, sem conta.',
 'faq.q5': 'Existe um plano gratuito?',
 'faq.a5': 'Sim. O plano gratuito inclui projetos ilimitados e todos os recursos principais. As exportações trazem uma pequena marca d\'água photoZseo e tag no nome do arquivo; Pro remove ambos.',
 'faq.q6': 'Posso cancelar a assinatura a qualquer momento?',
 'faq.a6': 'Sim. As assinaturas são faturadas pela App Store e podem ser canceladas a qualquer momento em Ajustes → ID Apple → Assinaturas. Você mantém o Pro até o fim do período atual.',
 'faq.q7': 'Para onde vão minhas fotos? Elas são enviadas para algum lugar?',
 'faq.a7': 'Para lugar nenhum. photoZseo processa cada foto no dispositivo. Nenhuma imagem ou metadado sai do seu telefone a menos que você mesmo compartilhe, exporte ou envie.',

