 'feature.seo-filenames.title': 'Nomes SEO e texto alternativo',
 'feature.seo-filenames.lead': 'Nomes de arquivo otimizados para busca gerados automaticamente como blue-leather-bag-front.webp — prontos para Google Imagens, Shopify, Amazon e todos os crawlers de e-commerce.',
 'feature.seo-filenames.b1.title': 'Rankeia no Google Imagens',
 'feature.seo-filenames.b1.desc': 'Separado por hífens, minúsculas, seguro para plataforma. O formato exato que mecanismos de busca preferem para rastreamento de produtos.',
 'feature.seo-filenames.b2.title': 'Unicode para qualquer idioma',
 'feature.seo-filenames.b2.desc': 'Turco, árabe, japonês, hindi — cada caractere é normalizado e romanizado quando importa.',
 'feature.seo-filenames.b3.title': 'Alt text em um toque',
 'feature.seo-filenames.b3.desc': 'Texto alternativo descritivo gerado do nome do produto, tag de direção e cena. Acessibilidade + SEO em um movimento.',
 'feature.seo-filenames.s1.title': 'Digite o nome do produto',
 'feature.seo-filenames.s1.desc': 'Bolsa de Couro Azul. É isso.',
 'feature.seo-filenames.s2.title': 'Escolha uma tag de direção',
 'feature.seo-filenames.s2.desc': 'Frente, trás, lado, detalhe, topo — seus nomes ficam organizados em todas as fotos.',
 'feature.seo-filenames.s3.title': 'Exporte para qualquer lugar',
 'feature.seo-filenames.s3.desc': 'O nome SEO viaja com seu arquivo para AirDrop, Shopify, email, Arquivos — onde você enviar.',
 'feature.platform-presets.title': '46 presets de plataforma',
 'feature.platform-presets.lead': 'Amazon pede 2000×2000. Etsy quer 3:4. TikTok Shop prefere 1:1. photoZseo já sabe — escolha a plataforma e aplicamos a especificação.',
 'feature.platform-presets.b1.title': 'Sempre atual',
 'feature.platform-presets.b1.desc': 'Cada versão atualiza as regras de tamanho, formato e peso para cada marketplace. Adeus guias desatualizados.',
 'feature.platform-presets.b2.title': 'Um toque, cada plataforma',
 'feature.platform-presets.b2.desc': 'Redimensione, comprima e formate nas especificações exatas publicadas pela Amazon, Etsy, Shopify, eBay e Walmart.',
 'feature.platform-presets.b3.title': 'Lote entre plataformas',
 'feature.platform-presets.b3.desc': 'Mesma foto, múltiplas exportações de plataforma em uma passagem — zipado e pronto para upload.',
 'feature.platform-presets.s1.title': 'Selecione sua plataforma',
 'feature.platform-presets.s1.desc': 'Amazon, Etsy, Shopify, TikTok Shop, Instagram — 46 para escolher.',
 'feature.platform-presets.s2.title': 'photoZseo aplica a especificação',
 'feature.platform-presets.s2.desc': 'Tamanho, proporção, formato, compressão e nome de arquivo todos definidos corretamente.',
 'feature.platform-presets.s3.title': 'Exporte e envie',
 'feature.platform-presets.s3.desc': 'Exporte para Shopify (CSV/XLSX/DOCX), AirDrop, Arquivos, Mail ou um zip — pronto para upload em massa.',
 'home.bandlabel': 'Otimizado para 46 plataformas',
 'home.howitworks': 'Como funciona',
 'home.howitworks.sub': 'Três passos. Um app. Todas as plataformas.',
 'home.step.shoot': 'Fotografe',
 'home.step.shoot.desc': 'Abra a câmera. Guias de corte, grade, indicador de nível e tags de direção prontos. Basta tocar no obturador.',
 'home.step.optimize': 'Otimize',
 'home.step.optimize.desc': 'photoZseo corta, redimensiona, comprime, renomeia com palavras-chave SEO e gera texto alternativo automaticamente. Tudo em segundo plano.',
 'home.step.sell': 'Venda',
 'home.step.sell.desc': 'Exporte como CSV/XLSX/DOCX, compartilhe via AirDrop ou envie ao Shopify. Suas fotos estão prontas — faça upload e comece a vender.',
