 'hero.cta': 'Baixar na App Store',
 'platforms.title': 'Feito para Todos os Marketplaces',
 'features.title': 'Recursos',
 'features.camera.title': 'Estúdio de Câmera Pro',
 'features.camera.desc': 'Câmera integrada com foco por toque, grade, indicador de nível, modo de disparo direcional, rajada e obturador por volume.',
 'features.archive.title': 'Arquivo de Projetos',
 'features.archive.desc': 'Organize todas as fotos de produto em pastas estilo Apple Files. Um projeto por produto — pastas coloridas, arrastar e soltar, renomear, duplicar.',
 'features.resize.title': 'Corte e Compressão Automáticos',
 'features.resize.desc': 'Corte, redimensionamento e compressão automáticos conforme especificações de cada plataforma. Modo qualidade ou modo tamanho de arquivo alvo. Saída JPEG, PNG, WebP.',
 'features.seo.title': 'Nomes SEO e Texto Alt',
 'features.seo.desc': 'Gere automaticamente nomes de arquivo e texto alternativo otimizados para busca a partir do nome do produto e tags de direção. Suporte Unicode para qualquer idioma.',
 'features.presets.title': 'Presets de Plataforma',
 'features.presets.desc': 'Presets de um toque para Amazon, Etsy, Shopify, Trendyol, Instagram, TikTok. Tamanho, formato e qualidade — tudo pré-configurado.',
 'features.video.title': 'Vídeo de Produto',
 'features.video.desc': 'Grave vídeos de produto diretamente no app. Corte e redimensionamento automáticos para as dimensões do projeto. Perfeito para Reels, TikTok e listagens.',
 'features.bgremoval.title': 'Remoção de Fundo',
 'features.bgremoval.desc': 'Remoção de fundo com IA em um toque. Substitua por branco, preto, cor personalizada ou PNG transparente para listagens profissionais.',
 'features.logo.title': 'Logo e Marca d\'Água',
 'features.logo.desc': 'Adicione seu logo de marca a cada exportação. Escolha entre 9 posições, ajuste tamanho e opacidade. Sua marca, automatizada.',
