 'privacy.thirdparty.title': 'तृतीय-पक्ष सेवाएं', 'privacy.thirdparty.apple': 'Apple App Store: खरीद और सदस्यता प्रबंधित करता है।', 'privacy.thirdparty.revenuecat': 'RevenueCat: सदस्यता स्थिति प्रबंधित करता है। उनकी गोपनीयता नीति revenuecat.com/privacy पर देखें।',
 'privacy.thirdparty.firebase': 'Firebase Crashlytics (Google): अनाम क्रैश रिपोर्ट और प्रदर्शन डायग्नोस्टिक्स एकत्र करता है। कोई IDFA नहीं, कोई विज्ञापन ट्रैकिंग नहीं। देखें firebase.google.com/support/privacy।',
 'privacy.thirdparty.shopify': 'Shopify (केवल एक्सपोर्ट): photoZseo, Shopify के सर्वर से कनेक्ट नहीं होता। ऐप आपकी प्रोडक्ट लिस्ट को CSV, XLSX या DOCX फ़ाइलों में एक्सपोर्ट करता है; उस फ़ाइल को आप खुद अपने Shopify Admin में अपलोड करते हैं। आपका डेटा डिवाइस से तभी जाता है जब आप एक्सपोर्ट फ़ाइल को सक्रिय रूप से शेयर या अपलोड करते हैं।',
 'privacy.marketplace.title': 'ऑनलाइन स्टोर और मार्केटप्लेस', 'privacy.marketplace.desc': 'ऑनलाइन स्टोर / मार्केटप्लेस एक वैकल्पिक सुविधा है। यदि आप कोई स्टोर प्रकाशित करना चुनते हैं, तो आप Google से साइन इन करते हैं और हम आपका ईमेल पता और नाम एकत्र करते हैं। यह जानकारी — आपके स्टोर विवरण और हमारी शर्तों को स्वीकार करने के रिकॉर्ड के साथ — हमारे इंफ्रास्ट्रक्चर प्रदाता Cloudflare पर संग्रहीत की जाती है, ताकि आपको स्टोर मालिक के रूप में पहचाना जा सके, स्टोरफ्रंट को आपके खाते से जोड़ा जा सके और स्टोर को प्रकाशित, संपादित या हटाने जैसे खाता-स्तरीय कार्य किए जा सकें। आप किसी भी समय हमसे संपर्क करके इस डेटा को हटाने का अनुरोध कर सकते हैं। यदि आप ऑनलाइन स्टोर / मार्केटप्लेस का उपयोग कभी नहीं करते, तो इनमें से कोई भी जानकारी एकत्र नहीं की जाती।', 'privacy.storage.title': 'डेटा संग्रहण', 'privacy.storage.desc': 'सभी प्रोजेक्ट डेटा, चित्र और सेटिंग्स आपके डिवाइस पर एन्क्रिप्टेड सैंडबॉक्स स्टोरेज में स्थानीय रूप से संग्रहीत हैं। आप कभी भी ऐप की सेटिंग्स से सब कुछ हटा सकते हैं।',
 'privacy.camera.title': 'कैमरा और फ़ोटो लाइब्रेरी एक्सेस', 'privacy.camera.desc': 'ऐप उत्पाद फ़ोटो कैप्चर और इंपोर्ट करने के लिए कैमरा और फ़ोटो लाइब्रेरी एक्सेस मांगता है। ये अनुमतियां वैकल्पिक हैं और आपके डिवाइस की सेटिंग्स से कभी भी रद्द की जा सकती हैं।',
 'privacy.biometric.title': 'बायोमेट्रिक प्रमाणीकरण',
 'privacy.biometric.desc': 'photoZseo Face ID, Touch ID या डिवाइस पासकोड का उपयोग करके एक वैकल्पिक ऐप लॉक सुविधा प्रदान करता है। बायोमेट्रिक डेटा पूरी तरह से आपके डिवाइस के ऑपरेटिंग सिस्टम द्वारा संसाधित होता है — photoZseo कभी भी आपके बायोमेट्रिक डेटा तक पहुंच, संग्रह या प्रसारण नहीं करता।',
