 'multicap.note.title': 'वास्तविक दुनिया का उदाहरण:',
 'multicap.note.body': 'एक बार शूट करें → Instagram के लिए 1080×1080 WebP + Trendyol के लिए 1200×1800 JPEG + YouTube के लिए 1920×1080 JPEG प्राप्त करें - सभी एक ही टैप से, सभी एक ही प्रोजेक्ट फ़ोल्डर में।',
 'rename.title': 'एक बार नाम बदलें. सब कुछ अपडेट.',
