 'rename.f.batch.t': '📦 बैच-सुरक्षित',
 'rename.f.batch.d': 'प्रति-दिशा अनुक्रम संरक्षित: सामने, पीछे, साइड की गिनती नए स्लग पर फिर से लागू की गई। कोई टकराव नहीं.',
 'rename.f.tx.t': '🔒 लेनदेन-सुरक्षित',
