 'archive.title': 'एक उत्पाद संग्रह, न कि केवल एक कैमरा',
 'archive.sub': 'photoZseo आपके उत्पादों के लिए एक डिजिटल फाइलिंग कैबिनेट है। हज़ारों आइटमों में खोजें. श्रेणी, ग्राहक या कंपनी के आधार पर समूह बनाएं। जो कुछ भी आप गलती से हटा देते हैं उसे पुनर्स्थापित करें।',
