 'privacy.thirdparty.title': 'تیسری پارٹی خدمات', 'privacy.thirdparty.apple': 'Apple App Store: خریداریاں اور سبسکرپشنز منظم کرتا ہے۔', 'privacy.thirdparty.revenuecat': 'RevenueCat: سبسکرپشن کی حیثیت منظم کرتا ہے۔ ان کی رازداری پالیسی revenuecat.com/privacy پر دیکھیں۔', 'privacy.thirdparty.firebase': 'Firebase Crashlytics (Google): گمنام کریش رپورٹس اور کارکردگی کی تشخیص جمع کرتا ہے۔ کوئی IDFA نہیں، کوئی اشتہاری ٹریکنگ نہیں۔ دیکھیں firebase.google.com/support/privacy۔',
 'privacy.thirdparty.shopify': 'Shopify (صرف ایکسپورٹ): photoZseo Shopify کے سرورز سے منسلک نہیں ہوتا۔ ایپ آپ کی پروڈکٹ لسٹ کو CSV، XLSX یا DOCX فائلوں کے طور پر ایکسپورٹ کرتی ہے؛ آپ خود اس فائل کو اپنے Shopify Admin پر اپ لوڈ کرتے ہیں۔ آپ کا ڈیٹا صرف اس وقت ڈیوائس سے نکلتا ہے جب آپ خود ایکسپورٹ فائل کو شیئر یا اپ لوڈ کریں۔',
 'privacy.marketplace.title': 'آن لائن اسٹور اور مارکیٹ پلیس', 'privacy.marketplace.desc': 'آن لائن اسٹور / مارکیٹ پلیس ایک اختیاری خصوصیت ہے۔ اگر آپ کوئی اسٹور شائع کرنے کا انتخاب کرتے ہیں تو آپ Google سے سائن اِن کرتے ہیں اور ہم آپ کا ای میل پتہ اور نام جمع کرتے ہیں۔ یہ معلومات — آپ کے اسٹور کی تفصیلات اور ہماری شرائط کو قبول کرنے کے ریکارڈ کے ساتھ — ہمارے انفراسٹرکچر فراہم کنندہ Cloudflare پر محفوظ کی جاتی ہیں، تاکہ آپ کو اسٹور مالک کے طور پر شناخت کیا جا سکے، اسٹور فرنٹ کو آپ کے اکاؤنٹ سے منسلک کیا جا سکے، اور اسٹور کو شائع، ترمیم یا ہٹانے جیسے اکاؤنٹ کی سطح کے کام انجام دیے جا سکیں۔ آپ کسی بھی وقت ہم سے رابطہ کر کے اس ڈیٹا کو حذف کرنے کی درخواست کر سکتے ہیں۔ اگر آپ آن لائن اسٹور / مارکیٹ پلیس کبھی استعمال نہیں کرتے تو ان میں سے کوئی معلومات جمع نہیں کی جاتی۔', 'privacy.storage.title': 'ڈیٹا ذخیرہ', 'privacy.storage.desc': 'تمام پروجیکٹ ڈیٹا، تصاویر اور سیٹنگز آپ کے ڈیوائس پر انکرپٹڈ سینڈ باکس اسٹوریج میں مقامی طور پر محفوظ ہیں۔ آپ کسی بھی وقت ایپ کی سیٹنگز سے تمام ڈیٹا حذف کر سکتے ہیں۔',
