 'privacy.collection.desc': "photoZseo تمام تصاویر مکمل طور پر آپ کے آلے پر پروسیس کرتی ہے۔ ہم آپ کی تصاویر کسی سرور پر اپ لوڈ، محفوظ یا منتقل نہیں کرتے۔ واحد استثنا اختیاری آن لائن اسٹور / مارکیٹ پلیس کی سہولت ہے، جس کی تفصیل نیچے دی گئی ہے — اگر آپ اسے استعمال کرنے کا انتخاب کریں تو اکاؤنٹ کی کچھ معلومات ہمارے سرورز کو بھیجی جاتی ہیں۔",
