 'aup.version': "ورژن 2026-05-31",
 'aup.intro.title': "اس پالیسی کا دائرہ",
 'aup.intro.desc': "یہ قابل قبول استعمال کی پالیسی photoZseo کی آن لائن اسٹور ہوسٹنگ سروس پر لاگو ہوتی ہے، جو بیچنے والے کو photozseo.com/store پر اور /market جیسے دریافت کے پلیٹ فارمز پر عوامی اسٹور فرنٹ شائع کرنے کی سہولت دیتی ہے۔ photoZseo صرف ہوسٹنگ اور اشاعت کے ٹولز فراہم کرتی ہے۔ وہ کوئی سامان نہیں بناتی، مہیا نہیں کرتی، معائنہ نہیں کرتی، ذخیرہ نہیں کرتی، روانہ نہیں کرتی اور نہ فروخت کرتی ہے، اور بیچنے والے اور خریدار کے درمیان کسی فروخت میں فریق نہیں ہے۔ بیچنے والے اپنی شائع کردہ ہر چیز کے مکمل ذمہ دار ہیں، اور اس بات کے بھی کہ وہ ہر اس جگہ قانونی ہو جہاں ان کا اسٹور دیکھا جا سکتا ہے اور سامان بھیجا جا سکتا ہے۔",
 'aup.prohibited.title': "ممنوعہ اشیا",
 'aup.prohibited.desc': "آپ درج ذیل میں سے کوئی چیز شائع، درج، پیش، فروغ یا اس سے منسلک نہیں کر سکتے۔ مثالیں وضاحت کے لیے ہیں، مکمل فہرست نہیں — اگر کوئی چیز کسی زمرے میں آتی ہے تو وہ ممنوع ہے چاہے اس کا نام نہ لیا گیا ہو۔",
 'aup.prohibited.weapons': "ہتھیار، آتشیں اسلحہ اور دھماکہ خیز مواد — ہر قسم کی بندوقیں، گولہ بارود، بلینک فائرنگ یا اسٹارٹر پستولیں، دھماکہ خیز مواد، اور انہیں جوڑنے کے پرزے یا کٹس۔",
 'aup.prohibited.drugs': "منشیات اور کنٹرول شدہ مادے — غیر قانونی منشیات اور نشہ آور اشیا، شیڈول شدہ مادے، اور بغیر قانونی اجازت کے پیش کی گئی صرف نسخے والی ادویات۔",
 'aup.prohibited.counterfeit': "جعلی اور حقوق کی خلاف ورزی کرنے والا سامان — نقل، \"1:1\" یا تقلیدی مصنوعات، بغیر اجازت کسی برانڈ یا لوگو کا استعمال کرنے والی اشیا، اور ہر وہ چیز جو املاک دانش کی خلاف ورزی کرے۔",
 'aup.prohibited.stolen': "چوری شدہ یا غیر قانونی طور پر حاصل کردہ سامان — چوری کی املاک یا غیر قانونی طور پر قبضے میں موجود سامان۔",
 'aup.prohibited.hate': "نفرت انگیز اور انتہا پسند مواد — نفرت، تشدد یا امتیاز کو فروغ دینے والا مواد، اور انتہا پسند، دہشت گرد یا نفرت پھیلانے والے گروہوں کی علامات یا پروپیگنڈا۔",
 'aup.prohibited.wildlife': "جنگلی حیات اور خطرے سے دوچار انواع کی مصنوعات — زندہ محفوظ جانور اور محفوظ انواع کی مصنوعات، جیسے ہاتھی دانت اور گینڈے کا سینگ۔",
 'aup.prohibited.regulated': "ریگولیٹڈ مصنوعات — تمباکو، سگریٹ، ای سگریٹ، ویپس اور نکوٹین مصنوعات، اور دیگر ایسا سامان جس پر عمر یا لائسنس کی سخت پابندی ہو۔",
 'aup.prohibited.fraud': "فراڈ اور جعلی دستاویزات — جعلی یا من گھڑت شناختی، سفری یا سرکاری دستاویزات، چوری شدہ یا کلون کیے گئے ادائیگی کے آلات، اور مالیاتی فراڈ میں استعمال ہونے والے ٹولز یا ڈیٹا۔",
 'aup.prohibited.bodyParts': "انسانی اعضا اور جسمانی حصے — فروخت کے لیے پیش کیے گئے انسانی اعضا، ٹشو، رطوبتیں یا باقیات، اور متعلقہ حیاتیاتی فضلہ۔",
 'aup.prohibited.adult': "بالغوں اور جنسی مواد — فحش یا صریح جنسی مواد، escort یا جنسی خدمات، اور جنسی مواد کے طور پر مارکیٹ کی جانے والی مصنوعات۔",
 'aup.conduct.title': "ممنوعہ طرز عمل",
 'aup.conduct.desc': "متعلقہ سامان کی نوعیت سے قطع نظر، درج ذیل طرز عمل کی اجازت نہیں:",
 'aup.conduct.fraud': "فراڈ اور دھوکہ دہی — اپنی، اپنے کاروبار یا سامان کی اصل، حالت، اصلیت یا دستیابی کی غلط نمائندگی، اور سامان نہ پہنچانے کی اسکیمیں۔",
 'aup.conduct.pricing': "گمراہ کن قیمتیں اور دعوے — جعلی \"اصل\" یا \"پہلے\" کی قیمتیں، مبالغہ آمیز رعایتیں، لالچ پر مبنی قیمتیں، جھوٹی قلت، جعلی جائزے، یا بلا ثبوت پروڈکٹ دعوے۔",
 'aup.conduct.spam': "اسپام اور ہیرا پھیری — بڑے پیمانے پر یا فریب پر مبنی لسٹنگز، کی ورڈ اسٹفنگ، حدود سے بچنے کے لیے متعدد اسٹور بنانا، یا تلاش اور دریافت میں ہیرا پھیری۔",
 'aup.conduct.impersonation': "کسی کا روپ دھارنا — کسی دوسرے شخص، برانڈ، کاروبار یا اتھارٹی ہونے کا دعویٰ کرنا، یا تعلق یا توثیق کا جھوٹا دعویٰ کرنا۔",
 'aup.conduct.unlawful': "غیر قانونی یا نقصان دہ استعمال — کسی قابل اطلاق قانون کی خلاف ورزی، دوسروں کے حقوق کی پامالی، میل ویئر پھیلانا، یا دوسروں کو ہراساں کرنا، دھمکانا یا نقصان پہنچانا۔",
 'aup.enforcement.title': "ہم اس کا نفاذ کیسے کرتے ہیں",
 'aup.enforcement.desc': "اس پالیسی کے نفاذ کے لیے photoZseo اپنی صوابدید پر، پیشگی اطلاع کے ساتھ یا اس کے بغیر:",
 'aup.enforcement.screening': "اشاعت کے وقت اسٹور کے مواد کی خودکار جانچ کر سکتی ہے، جس میں متن کی کی ورڈ جانچ اور پروڈکٹ تصاویر کی جانچ شامل ہے، اور ممنوعہ زمرے سے مطابقت رکھنے والے مواد کو بلاک یا مسترد کر سکتی ہے۔",
 'aup.enforcement.removal': "کسی بھی اسٹور، پروڈکٹ، تصویر یا مواد کو ہٹا سکتی، غیر فعال کر سکتی، چھپا سکتی یا فہرست سے خارج کر سکتی ہے۔ ہٹانے سے صرف عوامی صفحہ غیر فعال ہوتا ہے — آپ کی اپنی کلاؤڈ (مثلاً Google Drive) میں محفوظ اصل تصاویر حذف نہیں ہوتیں۔",
 'aup.enforcement.suspension': "کسی ایسے بیچنے والے کا اکاؤنٹ اور اسٹورز معطل یا مستقل طور پر ختم کر سکتی ہے جو اس پالیسی کی بار بار یا سنگین خلاف ورزی کرے۔",
 'aup.enforcement.waiver': "کسی حق سے دستبردار نہیں ہوتی — کسی خلاف ورزی پر کارروائی نہ کرنے کا مطلب اس یا کسی دوسری خلاف ورزی پر بعد میں کارروائی کا حق چھوڑنا نہیں۔",
 'aup.report.title': "خلاف ورزی کی رپورٹ کریں",
 'aup.report.desc': "اگر آپ سمجھتے ہیں کہ کوئی اسٹور یا لسٹنگ اس پالیسی یا قانون کی خلاف ورزی کرتی ہے تو ہمیں اسٹور کے پتے (photozseo.com/store/...) اور مسئلے کی تفصیل کے ساتھ ای میل کریں۔ ہم رپورٹس کا فوری جائزہ لینے اور مناسب کارروائی کرنے کی کوشش کرتے ہیں۔ جان بوجھ کر جھوٹی یا ناجائز رپورٹس جمع کرانا بذات خود خلاف ورزی ہے۔",
