 'mrules.prices.title': "قیمتیں",
 'mrules.prices.desc': "بیچنے والے اپنی قیمتیں خود طے کرتے ہیں۔ اگر کوئی لسٹنگ کم کی گئی قیمت کے ساتھ پہلی قیمت دکھاتی ہے تو پہلی قیمت وہ کم ترین قیمت ہونی چاہیے جو بیچنے والے نے کمی سے پہلے کے 30 دنوں میں وصول کی۔ دوسری کرنسی میں دکھائی گئی قیمتیں تخمینی تبادلہ ہیں۔ بیچنے والے کی اپنی کرنسی میں قیمت ہی پابند کن ہے۔",
 'mrules.safety.title': "پروڈکٹ کی حفاظت",
 'mrules.safety.desc': "EU میں صارفین کو بیچنے والوں کو لسٹنگ پر صنعت کار کی تفصیلات، پروڈکٹ کی شناخت اور کوئی انتباہ دکھانا لازم ہے۔ اگر آپ سمجھتے ہیں کہ کوئی پروڈکٹ غیر محفوظ ہے یا واپس منگوائی گئی ہے تو رپورٹ کریں۔ ہم غیر محفوظ مصنوعات ہٹاتے ہیں اور مارکیٹ کی نگرانی کرنے والے حکام سے تعاون کرتے ہیں۔",
 'mrules.notice.title': "غیر قانونی یا غیر محفوظ مواد کی رپورٹ کریں",
