 'mrules.notice.url': "لسٹنگ یا اسٹور کا درست پتہ (URL)؛",
 'mrules.notice.why': "آپ کیوں سمجھتے ہیں کہ یہ غیر قانونی، غیر محفوظ یا ہمارے قواعد کے خلاف ہے؛",
 'mrules.notice.contact': "آپ کا نام اور ای میل پتہ (بچوں کے جنسی استحصال کے مواد سے متعلق رپورٹس کے لیے اختیاری)؛",
 'mrules.notice.good': "ایک بیان کہ آپ کو نیک نیتی سے یقین ہے کہ آپ کی رپورٹ کی معلومات درست اور مکمل ہیں۔",
 'mrules.notice.after': "ہم آپ کی رپورٹ کی وصولی کی تصدیق کرتے ہیں، اس کا فوری اور غیر جانبداری سے جائزہ لیتے ہیں، اور آپ کو اپنے فیصلے سے آگاہ کرتے ہیں۔ املاک دانش کے مالکان یہی ذریعہ استعمال کر سکتے ہیں۔",
 'mrules.decisions.title': "ہمارے فیصلے",
 'mrules.decisions.desc': "اگر ہم کوئی لسٹنگ ہٹائیں، چھپائیں یا محدود کریں یا اسٹور معطل کریں تو ہم بیچنے والے کو وجہ بتاتے ہیں: حقائق، جس قاعدے یا قانون پر انحصار کیا گیا، آیا فیصلہ خودکار تھا، اور اپیل کیسے کی جائے۔ ہم حکام کے درست احکامات پر عمل کرتے ہیں اور متعلقہ افراد کو مطلع کرتے ہیں، سوائے اس کے کہ قانون منع کرے۔",
 'mrules.appeal.title': "شکایات اور اپیلیں",
 'mrules.appeal.desc': "بیچنے والے اور مواد کی رپورٹ کرنے والے افراد ہمارے نوٹس کا جواب دے کر یا support@photozseo.com پر ای میل کر کے چھ ماہ کے اندر ہمارے فیصلے کو چیلنج کر سکتے ہیں۔ ہر اپیل کا جائزہ ایک انسان لیتا ہے، کوئی خودکار نظام نہیں۔ آپ Digital Services Act کے تحت تصدیق شدہ عدالت سے باہر تنازعات کے تصفیے کے ادارے سے بھی رجوع کر سکتے ہیں یا عدالت جا سکتے ہیں۔ ترکی میں کاروباری بیچنے والے کے ساتھ صارفین کے تنازعات کے لیے صارفین کی ثالثی کمیٹیاں اور صارفین کی عدالتیں دستیاب ہیں۔",
 'mrules.misuse.title': "بار بار غلط استعمال",
 'mrules.misuse.desc': "جو بیچنے والے اکثر واضح طور پر غیر قانونی مواد شائع کرتے ہیں انہیں وارننگ کے بعد معطل کر دیا جاتا ہے۔ ہم ان افراد کی رپورٹس پر کارروائی روک سکتے ہیں جو اکثر واضح طور پر بے بنیاد رپورٹس بھیجتے ہیں۔",
 'mrules.ads.title': "اشتہارات اور نابالغ",
 'mrules.ads.desc': "مارکیٹ پلیس کوئی اشتہار نہیں دکھاتی اور صارفین کی پروفائلنگ نہیں کرتی۔ یہ بالغوں کے لیے ہے۔ بالغوں کا مواد اور عمر کی پابندی والی مصنوعات کی اجازت نہیں۔",
 'mrules.law.title': "قابل اطلاق قواعد",
 'mrules.law.desc': "یہ قواعد، جہاں لاگو ہوں، EU Digital Services Act (Regulation (EU) 2022/2065)، EU General Product Safety Regulation (Regulation (EU) 2023/988)، قیمتوں میں کمی اور جائزوں سے متعلق EU کے صارفین کے قانون، GDPR، ترکی کے ای کامرس قانون نمبر 6563 اور اس کے ضوابط، ترکی کے تحفظ صارف قانون نمبر 6502، KVKK اور امریکی INFORM Consumers Act کی پیروی کرتے ہیں۔ اس صفحے پر کوئی بات لازمی قانون کے تحت آپ کے حقوق کو محدود نہیں کرتی۔",
 'mrules.related': "متعلقہ:",
