 "privacy.controller2.desc": "photoZseo اس پالیسی میں بیان کردہ ذاتی ڈیٹا کا کنٹرولر ہے۔ آپ ہم سے support@photozseo.com پر رابطہ کر سکتے ہیں۔ ہم رازداری سے متعلق درخواستوں کا جواب انگریزی اور ترکی زبان میں دیتے ہیں۔ اگر آپ کو ہمارا مکمل قانونی نام اور ڈاک کا پتہ درکار ہو، مثلاً اپنے حقوق کے استعمال کے لیے یا سرکاری کارروائیوں کے لیے، تو ہمیں لکھیں اور ہم وہ فراہم کر دیں گے۔",
 "privacy.cookies.google": "Google سائن اِن: مارکیٹ پلیس اور اسٹور کے صفحات accounts.google.com سے Google کی سائن اِن اسکرپٹ لوڈ کرتے ہیں، اس لیے Google کو آپ کا IP ایڈریس جیسا تکنیکی ڈیٹا موصول ہوتا ہے۔ Google اپنی کوکیز صرف اسی صورت میں سیٹ کرتا ہے جب آپ سائن اِن بٹن استعمال کریں۔ Google کی رازداری کی پالیسی ملاحظہ کریں۔",
 "storeterms.removal2.desc": "اگر کوئی لسٹنگ یا اسٹور ان شرائط، قابلِ قبول استعمال کی پالیسی یا قانون کی خلاف ورزی کرے تو photoZseo اس لسٹنگ کو ہٹا سکتا ہے، چھپا سکتا ہے یا محدود کر سکتا ہے، یا اسٹور کو معطل یا بند کر سکتا ہے۔ ہم آپ کو وجوہات، حقائق، جس قاعدے پر ہم نے انحصار کیا اور اپیل کرنے کا طریقہ بتاتے ہیں۔ کسی قانونی ذمہ داری یا بار بار یا سنگین خلاف ورزیوں کے علاوہ دیگر وجوہات کی بنا پر پورا اسٹور بند کرنے سے پہلے، ہم EU میں موجود کاروباری فروخت کنندگان کو کم از کم 30 دن کا نوٹس دیتے ہیں، جیسا کہ ضابطہ (EU) 2019/1150 (Regulation (EU) 2019/1150) میں لازم ہے۔ ہٹانے سے صرف عوامی صفحہ غیر فعال ہوتا ہے؛ آپ کے اپنے کلاؤڈ اسٹوریج میں موجود آپ کی اصل تصاویر حذف نہیں کی جاتیں۔",
 "storeterms.changes2.desc": "ہم ان شرائط کو اپ ڈیٹ کر سکتے ہیں۔ ہم تبدیلیوں کا اعلان ان کے نافذ ہونے سے کم از کم 15 دن پہلے ای میل کے ذریعے یا ایپ میں کرتے ہیں، الا یہ کہ کوئی قانونی ذمہ داری یا سکیورٹی خطرہ زیادہ جلد تبدیلی کا تقاضا کرے۔ نئی شرائط لاگو ہونے سے پہلے آپ اپنا اسٹور بند کر سکتے ہیں۔ موجودہ ورژن اور تاریخ اوپر دکھائی گئی ہے۔",
 "storeterms.safety2.desc": "صرف محفوظ اور قواعد کے مطابق مصنوعات فروخت کریں۔ جب آپ EU کے صارفین کو فروخت کرتے ہیں تو ہر لسٹنگ میں، مثلاً مصنوعات کی تفصیل میں، صنعت کار کا نام اور ڈاک و برقی پتہ، جہاں لازم ہو وہاں EU میں ذمہ دار شخص، مصنوعات کی شناخت کرنے والی معلومات (جیسے قسم، بیچ یا سیریل نمبر) اور خریدار کی زبان میں کوئی بھی انتباہ یا حفاظتی معلومات دینا ضروری ہے۔ اگر کوئی مصنوعات واپس منگوائی جائے یا غیر محفوظ پائی جائے تو اسے فوراً ہٹا دیں اور اپنے خریداروں کو مطلع کریں۔",
