 "terms.law.title": "قابلِ اطلاق قانون اور تنازعات",
 "terms.law.desc": "یہ شرائط جمہوریہ ترکیہ (Republic of Türkiye) کے قوانین کے تحت ہیں۔ اگر آپ صارف ہیں تو آپ اپنے رہائشی ملک کے لازمی قوانین کا تحفظ بھی برقرار رکھتے ہیں، اور آپ اس ملک کی عدالتوں میں دعوے دائر کر سکتے ہیں۔ عدالت جانے سے پہلے، براہِ کرم support@photozseo.com پر ہم سے رابطہ کریں تاکہ ہم مسئلہ حل کرنے کی کوشش کر سکیں۔",
