 "mrules.safety2.desc": "EU کے صارفین کو فروخت کرنے والے فروخت کنندگان کو لسٹنگ میں، مثلاً مصنوعات کی تفصیل میں، صنعت کار کی تفصیلات، مصنوعات کی شناخت اور کوئی بھی انتباہ دینا ہوگا۔ اگر آپ سمجھتے ہیں کہ کوئی مصنوعات غیر محفوظ ہے یا واپس منگوائی گئی ہے تو اس کی اطلاع دیں۔ ہم غیر محفوظ مصنوعات کو ہٹاتے ہیں اور مارکیٹ کی نگرانی کے حکام کے ساتھ تعاون کرتے ہیں۔",
