 'privacy.camera.title': 'الوصول للكاميرا ومكتبة الصور', 'privacy.camera.desc': 'يطلب التطبيق الوصول إلى الكاميرا ومكتبة الصور لالتقاط واستيراد صور المنتجات. هذه الأذونات اختيارية ويمكن إلغاؤها في أي وقت من إعدادات جهازك.',
