 'faq.q1': 'الزامات اندازه عکس محصول آمازون چیست؟',
 'faq.a1': 'آمازون به تصاویر محصول بین ۱۰۰۰×۱۰۰۰ تا ۲۰۰۰×۲۰۰۰ پیکسل روی پس‌زمینه سفید خالص نیاز دارد. photoZseo این مشخصات را با یک لمس اعمال می‌کند — بدون تغییر اندازه دستی.',
 'faq.q2': 'بهترین اندازه جهانی عکس محصول چیست؟',
 'faq.a2': '۲۰۰۰×۲۰۰۰ پیکسل، مربع (۱:۱)، پس‌زمینه سفید — نیازهای تقریباً هر بازار را برآورده می‌کند: آمازون، Etsy، Shopify، eBay، Walmart و بیشتر.',
