 'faq.a3': 'بیش از ۶۰ پلتفرم شامل آمازون، Walmart، Etsy، Shopify، eBay، TikTok Shop، Instagram Shopping، Trendyol، Hepsiburada، Poshmark، Pinterest، Mercado Libre و AliExpress.',
 'faq.q4': 'آیا بدون اینترنت کار می‌کند؟',
 'faq.a4': 'بله. تغییر اندازه، فشرده‌سازی، تغییر نام SEO و حذف پس‌زمینه ۱۰۰٪ روی دستگاه شما اجرا می‌شوند. بدون آپلود، بدون ابر، بدون حساب.',
 'faq.q5': 'آیا پلن رایگان وجود دارد؟',
 'faq.a5': 'بله. پلن رایگان شامل پروژه‌های نامحدود و تمام ویژگی‌های اصلی است. خروجی‌ها دارای واترمارک کوچک photoZseo و برچسب نام فایل هستند؛ Pro هر دو را حذف می‌کند.',
 'faq.q6': 'آیا می‌توانم اشتراک را در هر زمان لغو کنم؟',
 'faq.a6': 'بله. اشتراک‌ها از طریق App Store صورتحساب می‌شوند و می‌توان در هر زمان از تنظیمات → Apple ID → اشتراک‌ها لغو کرد. Pro تا پایان دوره فعلی فعال می‌ماند.',
 'faq.q7': 'عکس‌های من کجا می‌روند؟ آیا جایی آپلود می‌شوند؟',
 'faq.a7': 'هیچ جا. photoZseo هر عکس را روی دستگاه پردازش می‌کند. هیچ تصویر یا متادیتایی گوشی شما را ترک نمی‌کند مگر اینکه شما خودتان به اشتراک بگذارید، صادر کنید یا ارسال کنید.',

