 'privacy.collection.photos': 'عکس‌ها: به صورت محلی روی دستگاه شما پردازش می‌شوند.', 'privacy.collection.account': 'اطلاعات حساب: photoZseo نیازی به حساب کاربری ندارد. هیچ ایمیل، نام کاربری یا اطلاعات شخصی جمع‌آوری نمی‌شود.', 'privacy.collection.purchase': 'داده‌های خرید: اطلاعات اشتراک و خرید توسط Apple (App Store) مدیریت می‌شود. ما به جزئیات پرداخت شما دسترسی نداریم.', 'privacy.collection.diagnostic': 'داده‌های تشخیصی: گزارش‌های ناشناس خرابی و معیارهای عملکرد ممکن است برای کمک به ما در رفع اشکالات و بهبود پایداری جمع‌آوری شوند. بدون شناسه شخصی، بدون شناسه تبلیغاتی، بدون ردیابی.',
 'privacy.thirdparty.title': 'خدمات شخص ثالث', 'privacy.thirdparty.apple': 'Apple App Store: خریدها و اشتراک‌ها را مدیریت می‌کند.', 'privacy.thirdparty.revenuecat': 'RevenueCat: وضعیت اشتراک را مدیریت می‌کند. سیاست حریم خصوصی آن‌ها را در revenuecat.com/privacy ببینید.', 'privacy.thirdparty.firebase': 'Firebase Crashlytics (Google): گزارش‌های ناشناس خرابی و تشخیص‌های عملکرد را جمع‌آوری می‌کند. بدون IDFA، بدون ردیابی تبلیغاتی. به firebase.google.com/support/privacy مراجعه کنید.',
 'privacy.thirdparty.shopify': 'Shopify (فقط خروجی): photoZseo به سرورهای Shopify متصل نمی‌شود. اپ فهرست محصولات شما را به‌صورت فایل‌های CSV، XLSX یا DOCX خروجی می‌گیرد؛ شما خودتان آن فایل را در پنل Shopify Admin بارگذاری می‌کنید. داده‌های شما تنها زمانی از دستگاهتان خارج می‌شوند که خودتان فایل خروجی را به اشتراک بگذارید یا آپلود کنید.',
 'privacy.storage.title': 'ذخیره‌سازی داده', 'privacy.storage.desc': 'تمام داده‌های پروژه، تصاویر و تنظیمات به صورت محلی روی دستگاه شما در فضای ذخیره‌سازی رمزنگاری‌شده و ایزوله ذخیره می‌شوند. می‌توانید تمام داده‌ها را در هر زمان از تنظیمات اپ حذف کنید.',
 'privacy.camera.title': 'دسترسی به دوربین و کتابخانه عکس', 'privacy.camera.desc': 'اپ برای گرفتن و وارد کردن عکس‌های محصول به دوربین و کتابخانه عکس دسترسی می‌خواهد. این مجوزها اختیاری هستند و در هر زمان از تنظیمات دستگاه قابل لغو هستند.',
 'privacy.biometric.title': 'احراز هویت بیومتریک', 'privacy.biometric.desc': 'photoZseo یک ویژگی اختیاری قفل اپ با استفاده از Face ID، Touch ID یا رمز عبور دستگاه ارائه می‌دهد. داده‌های بیومتریک کاملاً توسط سیستم عامل دستگاه شما پردازش می‌شوند — photoZseo هرگز به داده‌های بیومتریک شما دسترسی پیدا نمی‌کند، آن‌ها را ذخیره یا انتقال نمی‌دهد.',
 'privacy.children.title': 'حریم خصوصی کودکان', 'privacy.children.desc': 'photoZseo برای کودکان زیر ۱۳ سال طراحی نشده است.',
