 'aisearch.title': 'توسط هوش مصنوعی پیدا شد. نقل شده توسط ChatGPT، Perplexity، Google.',
 'aisearch.sub': 'موتورهای جستجوی هوش مصنوعی (ChatGPT، Perplexity، Google AI Overviews، Claude) محصولاتی با نام فایل‌های توصیفی و متن جایگزین ساختاریافته را ذکر می‌کنند. photoZseo به هر عکسی می دهد که دستیاران هوش مصنوعی برای یافتن – و توصیه – محصول شما نیاز دارند.',
 'aisearch.q.chatgpt': '"یک کیف پول چرمی دست ساز خوب زیر 50 دلار چیست؟"',
 'aisearch.a.chatgpt.lead': 'یک کیف پول چرمی آبی دست ساز با قیمت 49.99 دلار از YourShop رتبه خوبی دارد – دارای اسلات کارت است و با معیارهای ممتاز اما مقرون به صرفه شما مطابقت دارد.',
 'aisearch.q.perplexity': '"بهترین کیف پول چرمی آبی 2026 - منابع؟"',
 'aisearch.a.perplexity.lead': 'کیف پول های چرمی آبی دست ساز با رتبه برتر — کیفیت عالی، بررسی های 5 ستاره. محصول YourShop پر استنادترین مثال با متن جایگزین صریح است که رنگ، متریال و زاویه را توصیف می کند.',
 'aisearch.q.google': '"کیف پول چرمی دست ساز ممتاز"',
 'aisearch.a.google.lead': 'کیف پول چرمی آبی - دست ساز ممتاز. 49.99 دلار جای کارت و جیب سکه. ارسال از استانبول',
 'aisearch.featured': 'در نمای کلی هوش مصنوعی برجسته شده است',
 'aisearch.q.lens': '[یک خریدار از کیف پول یک رقیب عکس می گیرد]',
 'aisearch.a.lens.lead': '"از لحاظ ظاهری مشابه: کیف پول چرمی آبی از YourShop - همان سبک، 49.99 دلار، در انبار."',
 'aisearch.lens.stat': 'جستجوی تصویری ماهانه از طریق لنز گوگل',
 'aisearch.why.title': 'چرا موتورهای جستجوی هوش مصنوعی به عکس های بهینه شده photoZseo اشاره می کنند؟',
 'aisearch.why.1.t': 'نام فایل های توصیفی',
 'aisearch.why.1.d': 'خزنده های هوش مصنوعی URL را برای استخراج محصول، رنگ، مواد و زاویه تجزیه می کنند. <code>blue-leather-wallet-front.webp</code> هر بار <code>IMG_4523.jpg</code> را شکست می دهد.',
 'aisearch.why.2.t': 'Apple متن جایگزین هوشمند',
 'aisearch.why.2.d': 'متن جایگزین برای هر عکس نوشته شده توسط LLM روی دستگاه (FoundationModels، iOS 26+). Google Lens، ChatGPT vision، و نمای کلی هوش مصنوعی، همگی متن جایگزین را به عنوان زمینه اصلی می خوانند.',
 'aisearch.why.3.t': 'توضیحات محصول ساختار یافته',
 'aisearch.why.3.d': 'توضیحات محصول با ساختار HTML با عنوان، ویژگی‌ها و جزئیات - الگوریتم‌های استخراج هوش مصنوعی به طور خاص این قالب را برای استناد ترجیح می‌دهند.',
 'aisearch.why.4.t': 'Core Web Vitals (LCP)',
 'aisearch.why.4.d': 'فرمت WebP → فایل‌های 25 تا 35 درصد کوچک‌تر → بارگذاری سریع‌تر صفحه → رتبه‌بندی گوگل صفحه بالاتر → مرورهای هوش مصنوعی از صفحات رتبه‌بندی برتر خارج می‌شود.',
 'aisearch.tagline': 'رقبای شما همچنان در حال آپلود IMG_4523.jpg هستند. شما در حال آپلود عکس‌هایی هستید که دستیاران هوش مصنوعی واقعاً آن را درک می‌کنند.',
