 'faq.q1': 'Amazon 제품 사진 크기 요구사항은 무엇인가요?',
 'faq.a1': 'Amazon은 순백색 배경에서 1000×1000에서 2000×2000 픽셀 사이의 제품 이미지를 요구합니다. photoZseo는 이러한 사양을 한 번의 탭으로 적용합니다 — 수동 크기 조정 불필요.',
