 'feature.seo-filenames.s2.desc': '앞, 뒤, 옆, 디테일, 상단 — 파일명이 모든 사진에서 정리됩니다.',
 'feature.seo-filenames.s3.title': '어디든 내보내기',
 'feature.seo-filenames.s3.desc': 'SEO 파일명은 AirDrop, Shopify, 메일, 파일앱으로 — 보내는 곳 어디든 함께 이동합니다.',
 'feature.platform-presets.title': '46 플랫폼 프리셋',
 'feature.platform-presets.lead': 'Amazon은 2000×2000을 요구합니다. Etsy는 3:4를 원합니다. TikTok Shop은 1:1을 선호합니다. photoZseo는 이미 알고 있습니다 — 플랫폼을 선택하면 사양을 적용합니다.',
 'feature.platform-presets.b1.title': '항상 최신',
