 'feature.platform-presets.b2.desc': 'Amazon, Etsy, Shopify, eBay 및 Walmart가 게시한 정확한 사양으로 크기 조정, 압축 및 포맷.',
 'feature.platform-presets.b3.title': '플랫폼 간 일괄 처리',
