 'feature.platform-presets.s3.title': '내보내기 및 업로드',
 'feature.platform-presets.s3.desc': 'Shopify로 내보내기 (CSV/XLSX/DOCX), AirDrop, 파일앱, 메일 또는 zip — 대량 업로드 준비 완료.',
