 'features.resize.title': '자동 크롭 & 압축',
 'features.resize.desc': '플랫폼 사양에 맞춘 자동 크롭, 리사이즈, 압축. 품질 모드 또는 목표 파일 크기 모드. JPEG, PNG, WebP 출력.',
