 'features.bgremoval.title': '배경 제거',
 'features.bgremoval.desc': 'AI 기반 원탭 배경 제거. 흰색, 검정, 맞춤 색상 또는 투명 PNG로 교체하여 전문적인 리스팅 완성.',
