 'privacy.collection.title': '데이터 수집', 'privacy.collection.desc': 'photoZseo는 모든 이미지를 기기에서 완전히 처리합니다.',
 'privacy.collection.photos': '사진: 기기에서 로컬로 처리됩니다. 서버로 전송되지 않습니다.', 'privacy.collection.account': '계정 정보: photoZseo는 계정이 필요하지 않습니다. 이메일, 사용자 이름 또는 개인 정보가 수집되지 않습니다.', 'privacy.collection.purchase': '구매 데이터: 구독 및 구매 정보는 Apple(App Store)이 관리합니다. 당사는 결제 세부 정보에 접근할 수 없습니다.', 'privacy.collection.diagnostic': '진단 데이터: 버그 수정 및 안정성 향상을 위해 익명 충돌 로그 및 성능 지표가 수집될 수 있습니다. 개인 식별자 없음, 광고 ID 없음, 추적 없음.',
 'privacy.thirdparty.title': '제3자 서비스', 'privacy.thirdparty.apple': 'Apple App Store: 구매 및 구독 관리.', 'privacy.thirdparty.revenuecat': 'RevenueCat: 구독 상태 관리. revenuecat.com/privacy에서 개인정보 처리방침을 확인하세요.', 'privacy.thirdparty.firebase': 'Firebase Crashlytics(Google): 익명 충돌 보고서와 성능 진단을 수집합니다. IDFA 없음, 광고 추적 없음. firebase.google.com/support/privacy를 참조하세요.',
 'privacy.thirdparty.shopify': 'Shopify(내보내기 전용): photoZseo는 Shopify 서버에 연결하지 않습니다. 앱은 제품 목록을 CSV, XLSX 또는 DOCX 파일로 내보내고, 사용자가 직접 해당 파일을 Shopify Admin에 업로드합니다. 데이터는 사용자가 내보내기 파일을 적극적으로 공유하거나 업로드할 때에만 기기에서 나갑니다.',
 'privacy.storage.title': '데이터 저장', 'privacy.storage.desc': '모든 프로젝트 데이터, 이미지 및 설정은 기기의 암호화된 샌드박스 저장소에 로컬로 저장됩니다. 앱 설정에서 언제든지 모든 데이터를 삭제할 수 있습니다.',
 'privacy.camera.title': '카메라 및 사진 라이브러리 접근', 'privacy.camera.desc': '앱은 제품 사진 촬영 및 가져오기를 위해 카메라와 사진 라이브러리 접근을 요청합니다. 이러한 권한은 선택 사항이며 기기 설정에서 언제든지 취소할 수 있습니다.',
 'privacy.biometric.title': '생체 인증', 'privacy.biometric.desc': 'photoZseo는 Face ID, Touch ID 또는 기기 암호를 사용하는 선택적 앱 잠금 기능을 제공합니다. 생체 데이터는 기기의 운영 체제에서만 처리됩니다 — photoZseo는 생체 데이터에 접근하거나 저장하거나 전송하지 않습니다.',
 'privacy.children.title': '아동 개인정보', 'privacy.children.desc': 'photoZseo는 13세 미만 아동을 대상으로 하지 않습니다.',
