 'features.camera.title': "Studio de caméra professionnel",
 'features.camera.desc': "Appareil photo intégré avec mise au point par pression, superposition de grille, indicateur de niveau, mode de prise de vue directionnelle, capture en rafale et obturateur de volume.",
 'features.archive.title': "Archives du projet",
 'features.archive.desc': "Organisez toutes vos photos de produits dans des dossiers de style Apple Files. Un projet par produit : dossiers à code couleur, glisser-déposer, renommer, dupliquer.",
 'features.resize.title': "Redimensionnement et compression automatiques",
 'features.resize.desc': "Recadrez, redimensionnez et compressez automatiquement selon les spécifications exactes de la plate-forme. Mode qualité ou mode taille de fichier cible. Sortie JPEG, PNG, WebP.",
 'features.seo.title': "Noms de fichiers SEO et texte alternatif",
 'features.seo.desc': "Générez automatiquement des noms de fichiers et du texte alternatif optimisés pour la recherche à partir du nom du produit et des balises de direction. Prise en charge Unicode pour n'importe quelle langue.",
 'features.presets.title': "Préréglages de plate-forme",
 'features.presets.desc': "Préréglages en un seul clic pour Amazon, Etsy, Shopify, Trendyol, Instagram, TikTok. Taille, format et qualité, tous préconfigurés.",
 'features.video.title': "Vidéo du produit",
 'features.video.desc': "Enregistrez des vidéos de produits directement dans l'application. Recadrez et redimensionnez automatiquement aux dimensions de votre projet. Parfait pour les bobines, TikTok et les annonces.",
 'features.bgremoval.title': "Suppression de l'arrière-plan",
 'features.bgremoval.desc': "Suppression de l’arrière-plan en un seul clic grâce à l’IA. Remplacez par du blanc, du noir, une couleur personnalisée ou un PNG transparent pour les listes professionnelles.",
 'features.logo.title': "Superposition de logo et de filigrane",
 'features.logo.desc': "Ajoutez le logo de votre marque à chaque exportation. Choisissez parmi 9 positions, ajustez la taille et l'opacité. Votre image de marque, automatisée.",
 'features.batch.title': "Exportation par lots et Zip",
 'features.batch.desc': "Exportez des projets ou des dossiers entiers sous forme de fichiers zip. Partagez via AirDrop, e-mail ou l'application Fichiers - prêt pour le téléchargement groupé.",
 'features.ondevice.title': "100 % sur l'appareil et privé",
