 'blog.sub': "Notes sur les photos des produits, les spécifications du marché et les flux de travail qui font réellement gagner du temps aux vendeurs.",
 'home.headline': "Tirer. Optimiser.<br/><span class=\"hero-accent\">Vendre.</span>",
