 'faq.title': "Questions fréquemment posées",
 'faq.sub': "Tout ce que les vendeurs demandent avant de télécharger.",
 'faq.q1': "Quelles sont les exigences en matière de taille de photo de produit Amazon ?",
 'faq.a1': "Amazon nécessite des images de produits comprises entre 1 000 × 1 000 et 2 000 × 2 000 pixels sur un fond blanc pur. photoZseo applique ces spécifications en un seul clic – pas de redimensionnement manuel.",
 'faq.q2': "Quelle est la meilleure taille universelle de photo de produit ?",
 'faq.a2': "2 000 × 2 000 pixels, carré (1:1), fond blanc répond aux exigences de pratiquement tous les marchés : Amazon, Etsy, Shopify, eBay, Walmart et plus encore.",
 'faq.q3': "Combien de plates-formes photoZseo prend-il en charge ?",
 'faq.a3': "46 plateformes dont Amazon, Walmart, Etsy, Shopify, eBay, TikTok Shop, Instagram Shopping, Trendyol, Hepsiburada, Poshmark, Pinterest, Mercado Libre et AliExpress.",
 'faq.q4': "Est-ce que ça marche sans internet ?",
 'faq.a4': "Oui. Tous les redimensionnements, compressions, renommages SEO et suppressions d’arrière-plan s’exécutent à 100 % sur votre appareil. Aucun téléchargement, aucun cloud, aucun compte requis.",
 'faq.q5': "Existe-t-il un forfait gratuit ?",
 'faq.a5': "Oui. Le forfait gratuit comprend un nombre illimité de projets et toutes les fonctionnalités de base. Les exportations portent un petit filigrane photoZseo et une balise de nom de fichier ; Pro supprime les deux.",
 'faq.q6': "Puis-je annuler l'abonnement à tout moment ?",
 'faq.a6': "Oui. Les abonnements sont facturés via le App Store et peuvent être annulés à tout moment depuis Paramètres → Identifiant Apple → Abonnements. Vous conservez Pro jusqu'à la fin de la période en cours.",
 'faq.q7': "Où vont mes photos ? Sont-ils téléchargés quelque part ?",
 'faq.a7': "Nulle part. photoZseo traite chaque photo sur l'appareil. Aucune image ou métadonnée ne quitte votre téléphone à moins que vous ne la partagiez, n'exportiez ou ne la transfériez explicitement vous-même.",
 'specs.title': "Spécifications de la plate-forme en un coup d'œil",
