 'feature.seo-filenames.lead': "Noms de fichiers optimisés pour la recherche générés automatiquement, comme blue-leather-bag-front.webp, prêts pour Google Images, Shopify, Amazon et tous les robots d'exploration de commerce électronique.",
 'feature.seo-filenames.b1.title': "Classements sur Google Images",
 'feature.seo-filenames.b1.desc': "Séparés par des traits d'union, minuscules, sécurisés pour la plateforme. Le format de nom de fichier exact que les moteurs de recherche préfèrent pour l'exploration des produits.",
 'feature.seo-filenames.b2.title': "Unicode pour n'importe quelle langue",
 'feature.seo-filenames.b2.desc': "Turc, arabe, japonais, hindi : chaque caractère est normalisé et romanisé lorsqu'il est important.",
 'feature.seo-filenames.b3.title': "Texte alternatif en un seul clic",
 'feature.seo-filenames.b3.desc': "Texte alternatif descriptif généré à partir du nom de votre produit, de la balise de direction et de la scène. Accessibilité + SEO en un seul geste.",
 'feature.seo-filenames.s1.title': "Tapez le nom de votre produit",
 'feature.seo-filenames.s1.desc': "Sac en cuir bleu. C'est ça.",
 'feature.seo-filenames.s2.title': "Choisissez une balise de direction",
 'feature.seo-filenames.s2.desc': "Recto, verso, côté, détail, haut : vos noms de fichiers restent organisés sur chaque photo.",
 'feature.seo-filenames.s3.title': "Exporter n'importe où",
 'feature.seo-filenames.s3.desc': "Le nom de fichier SEO accompagne votre fichier dans AirDrop, Shopify, e-mail, Files – partout où vous l'envoyez.",
 'feature.platform-presets.title': "46 préréglages de plateforme",
 'feature.platform-presets.lead': "Amazon demande 2000×2000. Etsy veut 3:4. TikTok Shop préfère 1:1. photoZseo le sait déjà : choisissez la plate-forme et nous appliquons les spécifications.",
 'feature.platform-presets.b1.title': "Toujours à jour",
 'feature.platform-presets.b1.desc': "Chaque version actualise les règles de taille, de format et de poids des fichiers pour chaque marché. Fini les guides obsolètes.",
 'feature.platform-presets.b2.title': "Un clic, sur chaque plateforme",
 'feature.platform-presets.b2.desc': "Redimensionnez, compressez et formatez selon les spécifications exactes Amazon, Etsy, Shopify, eBay et Walmart publiées.",
 'feature.platform-presets.b3.title': "Lot sur plusieurs plates-formes",
 'feature.platform-presets.b3.desc': "Même photo, exportations sur plusieurs plates-formes en un seul passage : compressées et prêtes à être téléchargées.",
 'feature.platform-presets.s1.title': "Sélectionnez votre plateforme",
 'feature.platform-presets.s1.desc': "Amazon, Etsy, Shopify, TikTok Shop, Instagram — 46 au choix.",
 'feature.platform-presets.s2.title': "photoZseo applique la spécification",
 'feature.platform-presets.s2.desc': "La taille, le rapport hauteur/largeur, le format, la compression et le nom de fichier sont tous correctement définis.",
 'feature.platform-presets.s3.title': "Exporter et télécharger",
 'feature.platform-presets.s3.desc': "Exportez vers Shopify (CSV/XLSX/DOCX), AirDrop, Files, Mail ou un zip — prêt pour le téléchargement groupé.",
