 'delete.email.title': "Option 2 : par e-mail",
 'delete.email.desc': "Si vous ne parvenez pas à accéder à l'application, envoyez un e-mail à support@photozseo.com avec pour objet « Supprimer mes données » et nous vous guiderons tout au long du processus.",
