 'blog.kicker': "Fotografia per l'e-commerce",
 'blog.sub': "Appunti su foto di prodotto, specifiche dei marketplace e flussi di lavoro che fanno davvero risparmiare tempo ai venditori.",
 'home.headline': "Scatta. Ottimizza.<br/><span class=\"hero-accent\">Vendi.</span>",
