 'faq.title': "Domande frequenti",
 'faq.sub': "Tutto ciò che i venditori chiedono prima di scaricare.",
 'faq.q1': "Quali sono i requisiti di dimensione delle foto prodotto su Amazon?",
 'faq.a1': "Amazon richiede immagini di prodotto tra 1000×1000 e 2000×2000 pixel su sfondo bianco puro. photoZseo applica queste specifiche con un solo tocco, senza ridimensionamento manuale.",
 'faq.q2': "Qual è la miglior dimensione universale per le foto prodotto?",
 'faq.a2': "2000×2000 pixel, quadrata (1:1), sfondo bianco: soddisfa i requisiti di praticamente tutti i marketplace, tra cui Amazon, Etsy, Shopify, eBay, Walmart e altri.",
 'faq.q3': "Quante piattaforme supporta photoZseo?",
 'faq.a3': "46 piattaforme, tra cui Amazon, Walmart, Etsy, Shopify, eBay, TikTok Shop, Instagram Shopping, Trendyol, Hepsiburada, Poshmark, Pinterest, Mercado Libre e AliExpress.",
 'faq.q4': "Funziona senza internet?",
 'faq.a4': "Sì. Ridimensionamento, compressione, rinomina SEO e rimozione dello sfondo avvengono al 100% sul tuo dispositivo. Nessun caricamento, nessun cloud, nessun account necessario.",
 'faq.q5': "Esiste un piano gratuito?",
 'faq.a5': "Sì. Il piano gratuito include progetti illimitati e tutte le funzionalità principali. Le esportazioni riportano una piccola filigrana photoZseo e un tag nel nome file; con Pro vengono rimossi entrambi.",
 'faq.q6': "Posso annullare l'abbonamento in qualsiasi momento?",
 'faq.a6': "Sì. Gli abbonamenti vengono fatturati tramite l'App Store e possono essere annullati in qualsiasi momento da Impostazioni → ID Apple → Abbonamenti. Mantieni Pro fino alla fine del periodo in corso.",
 'faq.q7': "Dove finiscono le mie foto? Vengono caricate da qualche parte?",
 'faq.a7': "In nessun posto. photoZseo elabora ogni foto sul dispositivo. Nessuna immagine né metadato lascia mai il tuo telefono, a meno che tu non scelga esplicitamente di condividerli, esportarli o inviarli.",
 'specs.title': "Specifiche delle piattaforme a colpo d'occhio",
 'specs.sub': "Ogni marketplace ha le sue regole per le foto. Le rispettiamo per te.",
