 'feature.seo-filenames.title': "Nomi file SEO e testo alternativo",
 'feature.seo-filenames.lead': "Nomi file generati automaticamente e ottimizzati per i motori di ricerca, come blue-leather-bag-front.webp, pronti per Google Immagini, Shopify, Amazon e ogni crawler dell'e-commerce.",
 'feature.seo-filenames.b1.title': "Posizionamento su Google Immagini",
 'feature.seo-filenames.b1.desc': "Separati da trattini, in minuscolo, sicuri per ogni piattaforma. Esattamente il formato di nome file che i motori di ricerca preferiscono per la scansione dei prodotti.",
 'feature.seo-filenames.b2.title': "Unicode per qualsiasi lingua",
 'feature.seo-filenames.b2.desc': "Turco, arabo, giapponese, hindi: ogni carattere viene normalizzato e romanizzato quando serve.",
 'feature.seo-filenames.b3.title': "Testo alternativo con un tocco",
 'feature.seo-filenames.b3.desc': "Testo alternativo descrittivo generato dal nome del prodotto, dal tag di angolazione e dalla scena. Accessibilità e SEO in un'unica mossa.",
 'feature.seo-filenames.s1.title': "Digita il nome del prodotto",
 'feature.seo-filenames.s1.desc': "Borsa in pelle blu. Tutto qui.",
 'feature.seo-filenames.s2.title': "Scegli un tag di angolazione",
 'feature.seo-filenames.s2.desc': "Fronte, retro, lato, dettaglio, alto: i nomi file restano organizzati su ogni foto.",
 'feature.seo-filenames.s3.title': "Esporta ovunque",
 'feature.seo-filenames.s3.desc': "Il nome file SEO viaggia con il tuo file su AirDrop, Shopify, e-mail, File: ovunque tu lo invii.",
 'feature.platform-presets.title': "46 preset per piattaforma",
 'feature.platform-presets.lead': "Amazon richiede 2000×2000. Etsy vuole 3:4. TikTok Shop preferisce 1:1. photoZseo lo sa già: scegli la piattaforma e noi applichiamo le specifiche.",
 'feature.platform-presets.b1.title': "Sempre aggiornato",
 'feature.platform-presets.b1.desc': "Ogni versione aggiorna le regole su dimensioni, formato e peso del file per ogni marketplace. Basta guide obsolete.",
 'feature.platform-presets.b2.title': "Un tocco, ogni piattaforma",
 'feature.platform-presets.b2.desc': "Ridimensiona, comprimi e formatta secondo le specifiche esatte pubblicate da Amazon, Etsy, Shopify, eBay e Walmart.",
 'feature.platform-presets.b3.title': "Esportazione multipla tra piattaforme",
 'feature.platform-presets.b3.desc': "Stessa foto, più esportazioni per piattaforme diverse in un solo passaggio, in formato zip e pronte per il caricamento.",
 'feature.platform-presets.s1.title': "Seleziona la tua piattaforma",
 'feature.platform-presets.s1.desc': "Amazon, Etsy, Shopify, TikTok Shop, Instagram: 46 tra cui scegliere.",
 'feature.platform-presets.s2.title': "photoZseo applica le specifiche",
 'feature.platform-presets.s2.desc': "Dimensioni, proporzioni, formato, compressione e nome file impostati correttamente.",
 'feature.platform-presets.s3.title': "Esporta e carica",
 'feature.platform-presets.s3.desc': "Esporta verso Shopify (CSV/XLSX/DOCX), AirDrop, File, Mail o uno zip, pronto per il caricamento massivo.",
