 'delete.app.s5': "Conferma l'eliminazione",
 'delete.app.note': "Verranno eliminati definitivamente tutti i progetti, le immagini e le impostazioni dell'app.",
 'delete.email.title': "Opzione 2: via e-mail",
 'delete.email.desc': "Se non riesci ad accedere all'app, invia un'e-mail a support@photozseo.com con l'oggetto \"Delete My Data\" e ti guideremo nella procedura.",
 'delete.email.response': "Risponderemo entro 48 ore.",
