 'hero.title': "photoZseo",
 'hero.tagline': "Twoje kompletne studio zdjęć produktowych. Fotografuj, porządkuj, optymalizuj i eksportuj obrazy gotowe dla każdej platformy — wszystko na Twoim urządzeniu.",
 'hero.cta': "Pobierz z App Store",
