 'features.title': "Funkcje",
 'features.camera.title': "Profesjonalne studio aparatu",
 'features.camera.desc': "Wbudowany aparat z ostrością dotykową, siatką, poziomicą, trybem kierunku zdjęcia, zdjęciami seryjnymi i spustem migawki na przyciskach głośności.",
 'features.archive.title': "Archiwum projektów",
 'features.archive.desc': "Porządkuj wszystkie zdjęcia produktów w folderach w stylu aplikacji Pliki Apple. Jeden projekt na produkt — foldery oznaczone kolorami, przeciąganie i upuszczanie, zmiana nazwy, duplikowanie.",
 'features.resize.title': "Automatyczna zmiana rozmiaru i kompresja",
 'features.resize.desc': "Automatyczne kadrowanie, zmiana rozmiaru i kompresja zgodnie z dokładnymi wymaganiami platform. Tryb jakości lub tryb docelowego rozmiaru pliku. Wyjście JPEG, PNG, WebP.",
 'features.seo.title': "Nazwy plików SEO i teksty alternatywne",
 'features.seo.desc': "Automatyczne generowanie nazw plików i tekstów alternatywnych zoptymalizowanych pod wyszukiwarki na podstawie nazwy produktu i tagów kierunku. Obsługa Unicode dla każdego języka.",
 'features.presets.title': "Gotowe profile platform",
 'features.presets.desc': "Profile jednym dotknięciem dla Amazon, Etsy, Shopify, Trendyol, Instagram i TikTok. Rozmiar, format i jakość — wszystko skonfigurowane z góry.",
 'features.video.title': "Wideo produktowe",
 'features.video.desc': "Nagrywaj filmy produktowe bezpośrednio w aplikacji. Automatyczne kadrowanie i zmiana rozmiaru do wymiarów projektu. Idealne dla Reels, TikTok i ofert.",
 'features.bgremoval.title': "Usuwanie tła",
 'features.bgremoval.desc': "Usuwanie tła jednym dotknięciem z pomocą AI. Zastąp je bielą, czernią, dowolnym kolorem lub przezroczystym PNG dla profesjonalnych ofert.",
 'features.logo.title': "Logo i znak wodny",
 'features.logo.desc': "Dodaj logo marki do każdego eksportu. Wybierz jedną z 9 pozycji, dostosuj rozmiar i przezroczystość. Twój branding, zautomatyzowany.",
 'features.batch.title': "Eksport zbiorczy i ZIP",
 'features.batch.desc': "Eksportuj całe projekty lub foldery jako pliki ZIP. Udostępniaj przez AirDrop, e-mail lub aplikację Pliki — gotowe do masowego przesyłania.",
 'features.ondevice.title': "100% na urządzeniu i prywatnie",
