 'faq.title': "Najczęściej zadawane pytania",
 'faq.sub': "Wszystko, o co sprzedawcy pytają przed pobraniem.",
 'faq.q1': "Jakie są wymagania Amazon dotyczące rozmiaru zdjęć produktów?",
 'faq.a1': "Amazon wymaga zdjęć produktów o rozmiarze od 1000×1000 do 2000×2000 pikseli na czysto białym tle. photoZseo stosuje te wymagania jednym dotknięciem — bez ręcznej zmiany rozmiaru.",
 'faq.q2': "Jaki jest najlepszy uniwersalny rozmiar zdjęcia produktu?",
 'faq.a2': "2000×2000 pikseli, kwadrat (1:1), białe tło — spełnia wymagania praktycznie każdego marketplace'u: Amazon, Etsy, Shopify, eBay, Walmart i innych.",
 'faq.q3': "Ile platform obsługuje photoZseo?",
 'faq.a3': "46 platform, w tym Amazon, Walmart, Etsy, Shopify, eBay, TikTok Shop, Instagram Shopping, Trendyol, Hepsiburada, Poshmark, Pinterest, Mercado Libre i AliExpress.",
 'faq.q4': "Czy działa bez internetu?",
 'faq.a4': "Tak. Zmiana rozmiaru, kompresja, zmiana nazw SEO i usuwanie tła działają w 100% na Twoim urządzeniu. Bez przesyłania, bez chmury, bez konta.",
 'faq.q5': "Czy jest plan bezpłatny?",
 'faq.a5': "Tak. Plan bezpłatny obejmuje nieograniczoną liczbę projektów i wszystkie podstawowe funkcje. Eksporty zawierają mały znak wodny photoZseo i znacznik w nazwie pliku; Pro usuwa oba.",
 'faq.q6': "Czy mogę anulować subskrypcję w dowolnym momencie?",
 'faq.a6': "Tak. Subskrypcje są rozliczane przez App Store i można je anulować w dowolnym momencie w Ustawienia → Apple ID → Subskrypcje. Pro zachowujesz do końca bieżącego okresu.",
 'faq.q7': "Dokąd trafiają moje zdjęcia? Czy są gdzieś przesyłane?",
 'faq.a7': "Nigdzie. photoZseo przetwarza każde zdjęcie na urządzeniu. Żaden obraz ani metadane nie opuszczają Twojego telefonu, dopóki sam wyraźnie ich nie udostępnisz, nie wyeksportujesz lub nie wyślesz.",
