 'feature.seo-filenames.title': "Nazwy plików SEO i teksty alternatywne",
 'feature.seo-filenames.lead': "Automatycznie generowane nazwy plików zoptymalizowane pod wyszukiwarki, np. blue-leather-bag-front.webp — gotowe dla Grafiki Google, Shopify, Amazon i każdego robota indeksującego sklepy internetowe.",
 'feature.seo-filenames.b1.title': "Wysokie pozycje w Grafice Google",
 'feature.seo-filenames.b1.desc': "Oddzielone myślnikami, małymi literami, bezpieczne dla platform. Dokładnie taki format nazwy pliku, jaki wyszukiwarki preferują przy indeksowaniu produktów.",
 'feature.seo-filenames.b2.title': "Unicode dla każdego języka",
 'feature.seo-filenames.b2.desc': "Turecki, arabski, japoński, hindi — każdy znak jest normalizowany i w razie potrzeby zapisywany alfabetem łacińskim.",
 'feature.seo-filenames.b3.title': "Tekst alternatywny jednym dotknięciem",
 'feature.seo-filenames.b3.desc': "Opisowy tekst alternatywny generowany na podstawie nazwy produktu, tagu kierunku i sceny. Dostępność i SEO w jednym kroku.",
