 'feature.seo-filenames.s2.desc': "Przód, tył, bok, detal, góra — Twoje nazwy plików pozostają uporządkowane dla każdego zdjęcia.",
 'feature.seo-filenames.s3.title': "Eksportuj gdziekolwiek",
 'feature.seo-filenames.s3.desc': "Nazwa pliku SEO podróżuje razem z plikiem do AirDrop, Shopify, poczty e-mail, aplikacji Pliki — wszędzie, dokąd go wyślesz.",
 'feature.platform-presets.title': "46 profili platform",
 'feature.platform-presets.lead': "Amazon wymaga 2000×2000. Etsy chce 3:4. TikTok Shop preferuje 1:1. photoZseo już to wie — wybierz platformę, a my zastosujemy wymagania.",
 'feature.platform-presets.b1.title': "Zawsze aktualne",
 'feature.platform-presets.b1.desc': "Każda wersja odświeża zasady dotyczące rozmiaru, formatu i wagi pliku dla każdego marketplace'u. Koniec z nieaktualnymi poradnikami.",
 'feature.platform-presets.b2.title': "Jedno dotknięcie, każda platforma",
 'feature.platform-presets.b2.desc': "Zmiana rozmiaru, kompresja i format zgodnie z dokładnymi wymaganiami publikowanymi przez Amazon, Etsy, Shopify, eBay i Walmart.",
 'feature.platform-presets.b3.title': "Zbiorczo dla wielu platform",
