 'shopify.title': "Eksport do Shopify — CSV, XLSX i DOCX",
 'shopify.sub': "AI wypełnia każde pole — tytuł, opis, tagi, meta SEO, tekst alternatywny, wysyłkę. Eksportuj gotowe do przesłania pliki CSV, XLSX lub DOCX. Na urządzeniu. Bez kopiuj-wklej.",
 'shopify.score': "Wynik",
 'shopify.b1.title': "AI na urządzeniu.",
 'shopify.b1.desc': "Framework Vision analizuje Twoje zdjęcia. Bez kosztów API. Bez przesyłania do chmury.",
 'shopify.b2.title': "Eksport zbiorczy.",
 'shopify.b2.desc': "Wybierz wiele projektów i wyeksportuj je wszystkie naraz. Duplikaty wykrywane automatycznie po handle.",
 'shopify.b3.title': "Tekst alternatywny dla każdego zdjęcia.",
 'shopify.b3.desc': "Apple Intelligence (iOS 26+) pisze unikalny, 1-2-zdaniowy tekst alternatywny dla każdego obrazu.",
 'shopify.b4.title': "Bezpieczne domyślnie.",
 'shopify.b4.desc': "Produkty trafiają jako wersja robocza. Marżę, stan magazynowy i kategorię sprawdzasz przed publikacją.",
 'b2b.title': "Faktury proforma B2B w prosty sposób",
 'b2b.sub': "Generuj profesjonalne oferty w formacie PDF A4 dla klientów hurtowych — wiele walut, IBAN, Incoterms, kody HS, podpis cyfrowy, kwota słownie. 12 języków.",
 'b2b.f.currency.t': "20 walut",
 'b2b.f.currency.d': "₺ $ € £ ¥ ₩ ₹ ₽ R$ CHF i więcej — selektor dostosowany do ustawień regionalnych.",
 'b2b.f.iban.t': "Wiele IBAN",
 'b2b.f.iban.d': "Dodawaj nieograniczoną liczbę rachunków bankowych dla każdej waluty. Automatyczne grupowanie 4×4. Obsługa SWIFT.",
 'b2b.f.incoterms.t': "Incoterms 2020",
 'b2b.f.incoterms.d': "EXW · FOB · CIF · DAP · DDP — wybierz jedną, a zostanie wydrukowana na każdej ofercie.",
 'b2b.f.hs.t': "HS / GTİP / NCM",
 'b2b.f.hs.d': "Kody HS dla każdej pozycji + kraj pochodzenia. Zestawienie gotowe dla odprawy celnej na każdej stronie.",
 'b2b.f.sign.t': "Podpis cyfrowy",
 'b2b.f.sign.d': "Obraz podpisu osoby upoważnionej osadzony w każdym pliku PDF. Przechowywany z ochroną pliku.",
 'b2b.f.words.t': "Kwota słownie",
 'b2b.f.words.d': "Zgodnie z ustawieniami regionalnymi: TRY → „Türk Lirası”, USD → „US Dollars”. Wymagane dla ważności prawnej.",
 'story.title': "Story Composer — WhatsApp i Telegram",
 'story.sub': "Kreator relacji ze zdjęć i wideo z inteligentnymi naklejkami produktowymi. Kolejka rotacyjna dla każdego kontaktu. 7-dniowa przerwa, dzięki której nigdy nie wyślesz spamu temu samemu kupującemu dwa razy.",
 'story.status': "Status",
 'story.sticker.stock': "Zostało 5",
 'story.f.smart.t': "🏷️ Inteligentne naklejki",
 'story.f.smart.d': "Automatyczne wypełnianie ceny · stanu · rabatu · lokalizacji · daty · nazwy produktu z Twojego projektu.",
 'story.f.queue.t': "🔄 Kolejka kontaktów",
 'story.f.queue.d': "Publikowanie rotacyjne — każdy kontakt widzi inny produkt, zanim cokolwiek się powtórzy.",
 'story.f.cooldown.t': "⏱️ 7-dniowa przerwa",
 'story.f.cooldown.d': "Ten sam kupujący nigdy nie zobaczy tego samego produktu dwa razy w ciągu tygodnia.",
 'story.f.video.t': "🎬 Zdjęcie lub wideo",
 'story.f.video.d': "Twórz relacje z dowolnego zdjęcia lub filmu produktowego z aplikacji. Zapisz i udostępnij w 2 dotknięciach.",
 'multicap.title': "Jedna migawka. Wiele wyników.",
 'multicap.sub': "Zrób jedno zdjęcie. Aplikacja tworzy osobne, zoptymalizowane projekty w różnych rozmiarach, formatach i ustawieniach jakości — jednocześnie. Bez ponownego eksportu, bez drugiej sesji zdjęciowej.",
 'multicap.oneshot': "Jedno dotknięcie",
 'multicap.f.aspect.t': "3 proporcje obrazu",
 'multicap.f.aspect.d': "Kwadrat · Pion · Poziom — każdą włączaj niezależnie w Ustawieniach.",
 'multicap.f.format.t': "Mieszane formaty",
 'multicap.f.format.d': "WebP, JPEG, PNG, GIF — wybierz inny format dla każdych proporcji.",
 'multicap.f.size.t': "Różne rozmiary",
 'multicap.f.size.d': "Od 400×400 do 4096×4096 — ustawiane dla każdych proporcji. Co 100 px.",
 'multicap.f.quality.t': "Jakość dla każdej karty",
 'multicap.f.quality.d': "Ustaw kompresję 50–100% niezależnie dla każdego wyniku. Oszczędność miejsca, zachowana jakość.",
 'multicap.note.title': "Przykład z praktyki:",
 'multicap.note.body': "Zrób zdjęcie raz → otrzymasz 1080×1080 WebP dla Instagram + 1200×1800 JPEG dla Trendyol + 1920×1080 JPEG dla YouTube — wszystko jednym dotknięciem, wszystko w tym samym folderze projektu.",
 'rename.title': "Zmień nazwę raz. Wszystko się zaktualizuje.",
 'rename.sub': "Zmień nazwę produktu raz. Aplikacja kaskadowo zastosuje zmianę w slugu, tekście alternatywnym, tytule SEO, opisie meta, opisie produktu, wszystkich nazwach plików na dysku i folderze projektu — atomowo.",
 'rename.input.label': "✏️ Nazwa produktu",
 'rename.before': "Przed",
