 'rename.field.slug': "Slug",
 'rename.field.alt': "Tekst alternatywny",
 'rename.field.seo': "Tytuł SEO",
 'rename.field.meta': "Opis meta",
 'rename.field.files': "Nazwy plików na dysku",
 'rename.field.folder': "Folder projektu",
 'rename.f.unicode.t': "🌐 Pełny Unicode",
 'rename.f.unicode.d': "Turecki (ş→s, ç→c, ğ→g), chiński, japoński, arabski, koreański, cyrylica — wszystko transliterowane na slugi bezpieczne dla adresów URL.",
 'rename.f.cascade.t': "⚡ Atomowa kaskada",
 'rename.f.cascade.d': "Jedna zmiana nazwy aktualizuje slug + tekst alternatywny + SEO + meta + opis produktu + folder + każdy plik zdjęcia — w jednej transakcji.",
 'rename.f.batch.t': "📦 Bezpieczne zbiorczo",
 'rename.f.batch.d': "Numeracja według kierunku zostaje zachowana: liczniki przód, tył, bok są stosowane ponownie do nowego sluga. Bez kolizji.",
 'rename.f.tx.t': "🔒 Bezpieczne transakcyjnie",
 'rename.f.tx.d': "Jeśli coś się nie powiedzie w trakcie zmiany nazwy, cała zmiana zostanie wycofana. Twoje archiwum nigdy nie zostanie w połowie przemianowane.",
 'archive.title': "Archiwum produktów, nie tylko aparat",
 'archive.sub': "photoZseo to cyfrowa szafa na akta Twoich produktów. Przeszukuj tysiące pozycji. Grupuj według kategorii, klienta lub firmy. Przywracaj wszystko, co usuniesz przez przypadek.",
 'archive.search': "Szukaj produktów, klientów, telefonów…",
 'archive.chip.all': "Wszystkie",
